export const MARKETPLACE_SHELL_HTML = "<div class=\"app-shell\">\r\n    <!-- =========================================================\r\n         TOP NAVIGATION BAR\r\n         ========================================================= -->\r\n    <header class=\"top-nav\">\r\n      <div class=\"top-nav-inner\">\r\n        <!-- Brand Badge -->\r\n        <a href=\"/app\" class=\"brand-badge\" title=\"Chow45 Marketplace\">\r\n          <span>CHOW45</span>\r\n          <span class=\"badge-tag\">Marketplace</span>\r\n        </a>\r\n\r\n        <!-- Location Selector Pill -->\r\n        <button class=\"location-pill\" onclick=\"Chow45App.openLocationModal()\" title=\"Change delivery location\">\r\n          <svg width=\"15\" height=\"15\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><path d=\"M21 10c0 7-9 13-9 13s-9-6-9-13a9 9 0 0 1 18 0z\"/><circle cx=\"12\" cy=\"10\" r=\"3\"/></svg>\r\n          <span class=\"loc-text\" id=\"current-location-text\">Select delivery location</span>\r\n          <svg width=\"12\" height=\"12\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><polyline points=\"6 9 12 15 18 9\"/></svg>\r\n        </button>\r\n\r\n\r\n        <!-- Right Actions: Orders, Profile, Auth & Cart -->\r\n        <div class=\"nav-actions\">\r\n          <button id=\"nav-auth-btn\" class=\"nav-auth-pill\" onclick=\"Chow45Auth.open()\" title=\"Account & Sign In\">\r\n            <span class=\"nav-auth-icon\">👤</span>\r\n            <span class=\"nav-auth-label\">Sign In</span>\r\n          </button>\r\n\r\n          <button class=\"cart-pill-btn desktop-only-btn\" onclick=\"CustomerController.openOrderHistory()\" title=\"My Orders\" style=\"padding: 7px 12px;\">\r\n            <svg width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><path d=\"M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z\"/><polyline points=\"14 2 14 8 20 8\"/></svg>\r\n            <span class=\"desktop-only-text\" style=\"font-size: 0.8rem;\">Orders</span>\r\n          </button>\r\n\r\n          <button class=\"cart-pill-btn\" onclick=\"CustomerController.openCart()\" aria-label=\"View Shopping Cart\">\r\n            <svg width=\"17\" height=\"17\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.2\"><circle cx=\"9\" cy=\"21\" r=\"1\"/><circle cx=\"20\" cy=\"21\" r=\"1\"/><path d=\"M1 1h4l2.68 13.39a2 2 0 0 0 2 1.61h9.72a2 2 0 0 0 2-1.61L23 6H6\"/></svg>\r\n            <span class=\"cart-badge-count cart-count-badge\" style=\"display: none;\">0</span>\r\n          </button>\r\n\r\n          <a href=\"/\" class=\"landing-link-btn\" title=\"Waitlist Page\">Waitlist</a>\r\n        </div>\r\n      </div>\r\n    </header>\r\n\r\n    <!-- Prevent flash of customer marketplace UI on /vendor path -->\r\n    <script>\r\n      (function() {\r\n        if (typeof window !== 'undefined' && (window.location.pathname.startsWith('/vendor') || window.location.search.includes('role=vendor'))) {\r\n          document.documentElement.classList.add('on-vendor-path');\r\n        }\r\n      })();\r\n    </script>\r\n    <style>\r\n      html.on-vendor-path #view-customer { display: none !important; }\r\n      html.on-vendor-path #view-vendor { display: block !important; }\r\n    </style>\r\n\r\n    <!-- =========================================================\r\n         MAIN VIEWPORT\r\n         ========================================================= -->\r\n    <main class=\"main-viewport\">\r\n      <!-- -------------------------------------------------------\r\n           ROLE 1: CUSTOMER DISCOVERY & ORDERING VIEW\r\n           ------------------------------------------------------- -->\r\n      <section id=\"view-customer\" class=\"role-view active\">\r\n        <!-- 1A: Home Discovery Section -->\r\n        <div id=\"customer-home-section\">\r\n          <!-- Hero Search Experience (Point 4) -->\r\n          <div class=\"marketplace-hero\" style=\"background-color: #008751; background-image: url('/app/hero-food-bg.jpg'); background-size: cover; background-position: right center; background-repeat: no-repeat; min-height: 280px;\">\r\n            <div class=\"hero-content\">\r\n              <h1 class=\"hero-headline\">What are you craving today?</h1>\r\n              <p class=\"hero-subtitle\">Simple food discovery and fast delivery across Idimu, Egbeda, Ikeja, Lagos and OOU Sagamu.</p>\r\n\r\n              <div class=\"search-pill-container\">\r\n                <svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><circle cx=\"11\" cy=\"11\" r=\"8\"/><line x1=\"21\" y1=\"21\" x2=\"16.65\" y2=\"16.65\"/></svg>\r\n                <input type=\"text\" id=\"market-search-input\" class=\"search-pill-input\" placeholder=\"What are you craving? (e.g. Jollof Rice, Suya, Amala)\" />\r\n                <button class=\"search-pill-btn\" onclick=\"document.getElementById('market-search-input').focus()\">Search</button>\r\n              </div>\r\n            </div>\r\n          </div>\r\n\r\n          <!-- Filter Chips (Point 6) -->\r\n          <div style=\"display: flex; gap: 8px; overflow-x: auto; padding-bottom: 8px; margin-bottom: var(--space-20); scrollbar-width: none;\">\r\n            <button class=\"filter-chip active\" data-filter=\"all\" onclick=\"CustomerController.setFilter('all')\">All Food</button>\r\n            <button class=\"filter-chip\" data-filter=\"fast\" onclick=\"CustomerController.setFilter('fast')\">⚡ Fast Delivery (<25m)</button>\r\n            <button class=\"filter-chip\" data-filter=\"budget\" onclick=\"CustomerController.setFilter('budget')\">🎓 Budget Friendly (≤₦2k)</button>\r\n            <button class=\"filter-chip\" data-filter=\"rating\" onclick=\"CustomerController.setFilter('rating')\">★ Top Rated (4.8+)</button>\r\n          </div>\r\n\r\n          <!-- Circular Food Category Buttons (Point 5) -->\r\n          <div class=\"section-header\">\r\n            <h2 class=\"section-title\">Food Categories</h2>\r\n            <span class=\"section-link\" onclick=\"CustomerController.selectCategory('all')\">View all</span>\r\n          </div>\r\n          <div id=\"categories-container\" class=\"category-scroll\">\r\n            <!-- Dynamic circular food categories injected by customer.js -->\r\n          </div>\r\n\r\n          <!-- Dynamic Discovery Sections (Popular, Fast Delivery, Stores) -->\r\n          <div id=\"discovery-sections-container\">\r\n            <!-- Injected by customer.js -->\r\n          </div>\r\n        </div>\r\n\r\n        <!-- 1B: Restaurant Menu Detail Section (Initially hidden) -->\r\n        <div id=\"customer-store-section\" style=\"display: none;\">\r\n          <button class=\"back-btn\" onclick=\"CustomerController.closeStoreMenu()\">\r\n            <svg width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"19\" y1=\"12\" x2=\"5\" y2=\"12\"/><polyline points=\"12 19 5 12 12 5\"/></svg>\r\n            Back to Restaurants\r\n          </button>\r\n\r\n          <div class=\"store-view-header\">\r\n            <img id=\"store-detail-banner\" class=\"store-banner-hero\" src=\"\" alt=\"Restaurant Banner\" />\r\n            <div class=\"store-header-body\">\r\n              <div style=\"display: flex; justify-content: space-between; align-items: flex-start;\">\r\n                <div>\r\n                  <h2 id=\"store-detail-name\" style=\"font-family: var(--font-display); font-size: 1.6rem; font-weight: 800; margin-bottom: 4px;\"></h2>\r\n                  <p id=\"store-detail-tags\" style=\"color: var(--c-text-secondary); font-size: 0.85rem; margin-bottom: 8px;\"></p>\r\n                </div>\r\n                <button class=\"action-btn-secondary\" style=\"padding: 6px 12px; font-size: 0.8rem;\" onclick=\"window.chowApp.toast('Store saved to favorites ❤️', 'success')\">\r\n                  Favorite\r\n                </button>\r\n              </div>\r\n              <div id=\"store-detail-meta\" style=\"font-size: 0.82rem; font-weight: 600; color: var(--c-text-secondary);\"></div>\r\n            </div>\r\n          </div>\r\n\r\n          <h3 class=\"section-title\" style=\"margin-bottom: var(--space-16);\">Menu</h3>\r\n          <div id=\"store-dishes-grid\" class=\"menu-items-grid\">\r\n            <!-- Dynamic dishes injected by customer.js -->\r\n          </div>\r\n        </div>\r\n\r\n        <!-- 1C: Live Mapbox Order Tracking Section (Point 16 & 17) -->\r\n        <div id=\"customer-tracking-section\" style=\"display: none;\">\r\n          <button class=\"tracking-back-btn\" onclick=\"CustomerController.closeTracking()\">\r\n            ← Back to food menu\r\n          </button>\r\n\r\n          <div class=\"tracking-screen\">\r\n            <!-- Mapbox Container -->\r\n            <div class=\"map-viewport\">\r\n              <div id=\"mapbox-canvas\"></div>\r\n            </div>\r\n\r\n            <!-- Floating Live Status Bottom Sheet -->\r\n            <div class=\"tracking-overlay-card\">\r\n              <div class=\"tracking-header-row\">\r\n                <div>\r\n                  <span style=\"font-size: 0.75rem; font-weight: 700; color: var(--c-text-muted); text-transform: uppercase;\">Order #<span id=\"track-order-id\"></span></span>\r\n                  <h3 id=\"track-status-heading\" class=\"status-headline\">Your food is being prepared</h3>\r\n                </div>\r\n                <div id=\"track-eta-badge\" class=\"status-eta-pill\">Est: 20 mins</div>\r\n              </div>\r\n\r\n              <!-- Progress Stepper -->\r\n              <div class=\"tracking-stepper\">\r\n                <div class=\"stepper-segment completed\"></div>\r\n                <div class=\"stepper-segment active\"></div>\r\n                <div class=\"stepper-segment\"></div>\r\n                <div class=\"stepper-segment\"></div>\r\n                <div class=\"stepper-segment\"></div>\r\n              </div>\r\n\r\n              <!-- Rider Dispatch Profile -->\r\n              <div class=\"rider-dispatch-card\">\r\n                <div class=\"rider-avatar-wrap\">\r\n                  <img class=\"rider-avatar\" src=\"https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?w=150&auto=format&fit=crop&q=80\" alt=\"Rider\" />\r\n                  <div>\r\n                    <div class=\"rider-name\">David Adeleke (Chow45 Rider)</div>\r\n                    <div class=\"rider-rating\">★ 4.9 • Bajaj Boxer 150 (LAG-452)</div>\r\n                  </div>\r\n                </div>\r\n                <button class=\"rider-action-btn\" title=\"Call Rider\" onclick=\"window.chowApp.toast('Calling David (+234 812 490 2819)...', 'info')\">\r\n                  <svg width=\"18\" height=\"18\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.2\"><path d=\"M22 16.92v3a2 2 0 0 1-2.18 2 19.79 19.79 0 0 1-8.63-3.07 19.5 19.5 0 0 1-6-6 19.79 19.79 0 0 1-3.07-8.67A2 2 0 0 1 4.11 2h3a2 2 0 0 1 2 1.72 12.84 12.84 0 0 0 .7 2.81 2 2 0 0 1-.45 2.11L8.09 9.91a16 16 0 0 0 6 6l1.27-1.27a2 2 0 0 1 2.11-.45 12.84 12.84 0 0 0 2.81.7A2 2 0 0 1 22 16.92z\"/></svg>\r\n                </button>\r\n              </div>\r\n\r\n              <!-- 4-Digit Security Dropoff PIN -->\r\n              <div class=\"pin-security-box\">\r\n                <span>Give this 4-digit PIN to rider upon arrival:</span>\r\n                <span id=\"track-order-pin\" class=\"pin-code\">4528</span>\r\n              </div>\r\n\r\n              <div style=\"display: flex; justify-content: space-between; font-size: 0.78rem; color: var(--c-text-muted); margin-top: 10px;\">\r\n                <span>Pickup: <strong id=\"track-store-name\" style=\"color: var(--c-text-primary);\">Restaurant</strong></span>\r\n                <span>Dropoff: <strong id=\"track-dest-address\" style=\"color: var(--c-text-primary);\">9 Goshen Ave</strong></span>\r\n              </div>\r\n            </div>\r\n          </div>\r\n        </div>\r\n      </section>\r\n\r\n      <!-- -------------------------------------------------------\r\n           ROLE 2: VENDOR / RESTAURANT PORTAL\r\n           ------------------------------------------------------- -->\r\n      <section id=\"view-vendor\" class=\"role-view\">\r\n        <div class=\"vendor-dashboard\">\r\n\r\n          <!-- ── Verification Holding Screen ─────────────────────── -->\r\n          <div id=\"vendor-holding-screen\" class=\"vnd-holding\" style=\"display: none;\">\r\n            <div class=\"vnd-holding-card\">\r\n              <div class=\"vnd-holding-icon\">⏳</div>\r\n              <h2 class=\"vnd-holding-title\">Account Under Verification</h2>\r\n              <p class=\"vnd-holding-text\">Our team is reviewing your details. You will be notified once approved.</p>\r\n              <div id=\"vnd-holding-reason\" class=\"vnd-holding-note\" style=\"display: none;\"></div>\r\n              <button class=\"vnd-btn vnd-btn-secondary vnd-btn-big\" onclick=\"VendorController.retryApplication()\">Edit My Application</button>\r\n              <p class=\"vnd-holding-small\">Food publishing is disabled while your account is under review.</p>\r\n            </div>\r\n          </div>\r\n\r\n          <!-- ── Main Vendor Dashboard ────────────────────────────── -->\r\n          <div id=\"vendor-main-dashboard\">\r\n\r\n            <!-- Desktop has no bottom bar, so the same four destinations are\r\n                 offered here instead of the old five-tab subnav. -->\r\n            <nav class=\"vendor-topnav\" data-nav-for=\"vendor\" aria-label=\"Vendor Sections\" hidden>\r\n              <button class=\"vnd-topnav-btn active\" data-vendor-tab=\"food\" onclick=\"VendorController.switchSubTab('food')\">\r\n                <span aria-hidden=\"true\">🍗</span> Foods\r\n              </button>\r\n              <button class=\"vnd-topnav-btn\" data-vendor-tab=\"orders\" onclick=\"VendorController.switchSubTab('orders')\">\r\n                <span aria-hidden=\"true\">🍳</span> Active orders\r\n                <span class=\"vendor-orders-badge-count vnd-topnav-badge\" style=\"display:none;\">0</span>\r\n              </button>\r\n              <button class=\"vnd-topnav-btn\" data-vendor-tab=\"store\" onclick=\"VendorController.switchSubTab('store')\">\r\n                <span aria-hidden=\"true\">🏪</span> Store\r\n              </button>\r\n              <button class=\"vnd-topnav-btn\" data-vendor-tab=\"money\" onclick=\"VendorController.switchSubTab('money')\">\r\n                <span aria-hidden=\"true\">💰</span> Earnings\r\n              </button>\r\n            </nav>\r\n\r\n            <!-- SUB-TAB 1: FOOD (Primary & Star Screen - Points 1 & 2) -->\r\n            <div id=\"vnd-tab-pane-food\" class=\"vnd-tab-pane active\">              <div class=\"vnd-food-header\">\r\n                <div>\r\n                  <h1 class=\"vnd-food-title\">My Food</h1>\r\n                  <p class=\"vnd-food-subtitle\">Add and manage the food you sell.</p>\r\n                </div>\r\n                <button class=\"vnd-btn-add-food-star\" onclick=\"VendorController.openAddFoodFlow()\">\r\n                  <span class=\"plus-sign\">＋</span> Add Food\r\n                </button>\r\n              </div>\r\n\r\n              <!-- Category filter chips (Point 29) -->\r\n              <div class=\"vnd-category-bar\" id=\"vnd-category-bar\">\r\n                <button class=\"vnd-cat-chip active\" data-cat=\"all\" onclick=\"VendorController.filterCategory('all')\">All</button>\r\n                <button class=\"vnd-cat-chip\" data-cat=\"rice\" onclick=\"VendorController.filterCategory('rice')\">Rice</button>\r\n                <button class=\"vnd-cat-chip\" data-cat=\"soups\" onclick=\"VendorController.filterCategory('soups')\">Soups</button>\r\n                <button class=\"vnd-cat-chip\" data-cat=\"swallows\" onclick=\"VendorController.filterCategory('swallows')\">Swallow</button>\r\n                <button class=\"vnd-cat-chip\" data-cat=\"drinks\" onclick=\"VendorController.filterCategory('drinks')\">Drinks</button>\r\n                <button class=\"vnd-cat-chip\" data-cat=\"snacks\" onclick=\"VendorController.filterCategory('snacks')\">Snacks</button>\r\n                <button class=\"vnd-cat-chip\" data-cat=\"grills\" onclick=\"VendorController.filterCategory('grills')\">Grills</button>\r\n              </div>\r\n\r\n              <!-- Auto-saved Vendor Drafts Section -->\r\n              <div id=\"vnd-drafts-section\" class=\"vnd-drafts-section\" style=\"display: none; margin-bottom: 20px;\"></div>\r\n\r\n              <!-- Main Three Sections: Available & Out of Stock (Point 2) -->\r\n              <div id=\"vnd-food-sections-wrap\">\r\n                <!-- Section 1: Available -->\r\n                <div class=\"vnd-menu-section\" id=\"vnd-available-section\">\r\n                  <div class=\"vnd-section-divider\">\r\n                    <span class=\"vnd-section-heading\">Available</span>\r\n                    <span class=\"vnd-section-count\" id=\"vnd-available-count\">0</span>\r\n                  </div>\r\n                  <div id=\"vnd-available-list\" class=\"vnd-cards-grid\">\r\n                    <!-- Injected by vendor.js -->\r\n                  </div>\r\n                </div>\r\n\r\n                <!-- Section 2: Out of stock -->\r\n                <div class=\"vnd-menu-section\" id=\"vnd-outofstock-section\">\r\n                  <div class=\"vnd-section-divider\">\r\n                    <span class=\"vnd-section-heading\">Out of stock</span>\r\n                    <span class=\"vnd-section-count\" id=\"vnd-outofstock-count\">0</span>\r\n                  </div>\r\n                  <div id=\"vnd-outofstock-list\" class=\"vnd-cards-grid\">\r\n                    <!-- Injected by vendor.js -->\r\n                  </div>\r\n                </div>\r\n              </div>\r\n\r\n              <!-- Empty state (Point 45) -->\r\n              <div id=\"vnd-food-empty-state\" class=\"vnd-empty-menu-box\" style=\"display: none;\">\r\n                <div class=\"vnd-empty-plate-icon\">🍲</div>\r\n                <h3 class=\"vnd-empty-h\">Your menu is empty.</h3>\r\n                <p class=\"vnd-empty-p\">Add your first food and start selling.</p>\r\n                <button class=\"vnd-btn-add-food-star\" onclick=\"VendorController.openAddFoodFlow()\">＋ Add Food</button>\r\n              </div>\r\n            </div>\r\n\r\n            <!-- SUB-TAB 2: ORDERS -->\r\n            <div id=\"vnd-tab-pane-orders\" class=\"vnd-tab-pane\">\r\n              <div class=\"vnd-card\">\r\n                <div class=\"vnd-card-head\">\r\n                  <h3>Kitchen Pipeline</h3>\r\n                  <span class=\"vnd-live\">● Live Orders</span>\r\n                </div>\r\n                <div class=\"vendor-tabs vnd-tabs\">\r\n                  <button class=\"vendor-tab-btn vnd-tab active\" data-tab=\"new\" onclick=\"VendorController.setTab('new')\">\r\n                    🔴 New Orders <span id=\"vendor-count-new\" class=\"tab-count\">0</span>\r\n                  </button>\r\n                  <button class=\"vendor-tab-btn vnd-tab\" data-tab=\"preparing\" onclick=\"VendorController.setTab('preparing')\">\r\n                    🟡 Preparing <span id=\"vendor-count-preparing\" class=\"tab-count\">0</span>\r\n                  </button>\r\n                  <button class=\"vendor-tab-btn vnd-tab\" data-tab=\"complete\" onclick=\"VendorController.setTab('complete')\">\r\n                    🟢 Completed / In Transit\r\n                  </button>\r\n                </div>\r\n                <div id=\"vendor-orders-list\" class=\"kitchen-orders-list\">\r\n                  <!-- Injected by vendor.js -->\r\n                </div>\r\n              </div>\r\n            </div>\r\n\r\n            <!-- SUB-TAB 3: MONEY -->\r\n            <div id=\"vnd-tab-pane-money\" class=\"vnd-tab-pane\">\r\n              <div class=\"vnd-empty vnd-empty-sm\">\r\n                <div class=\"vnd-empty-emoji\" aria-hidden=\"true\">💳</div>\r\n                <div class=\"vnd-empty-title\">Earnings &amp; payouts</div>\r\n                <div class=\"vnd-empty-hint\">\r\n                  Your balance, earnings history and bank payouts will appear here once\r\n                  you start selling. Nothing is shown until real order earnings come in.\r\n                </div>\r\n                <a class=\"vnd-btn vnd-btn-secondary\" href=\"/vendor/food\" style=\"margin-top: 16px;\">\r\n                  Add your first dish\r\n                </a>\r\n              </div>\r\n            </div>\r\n\r\n            <!-- SUB-TAB 5: STORE (profile, open/close toggle & settings) -->\r\n            <div id=\"vnd-tab-pane-store\" class=\"vnd-tab-pane\">\r\n              <div class=\"vendor-store-banner\">\r\n                <div class=\"vendor-profile-info\">\r\n                  <img id=\"vendor-store-avatar\" class=\"vendor-avatar\" src=\"\" alt=\"Store\" />\r\n                  <div>\r\n                    <h2 id=\"vendor-store-name\" class=\"vendor-title\">Your Store</h2>\r\n                    <div id=\"vendor-store-location\" class=\"vendor-location-tag\">Set your pickup/delivery address</div>\r\n                    <div id=\"vendor-store-hours\" class=\"vendor-hours-tag\">🕐 Set your operating hours</div>\r\n                  </div>\r\n                </div>\r\n\r\n                <div class=\"vendor-header-actions\">\r\n                  <div class=\"store-status-toggle\">\r\n                    <div id=\"vendor-open-toggle\" class=\"toggle-switch on\" onclick=\"VendorController.toggleStoreStatus()\">\r\n                      <div class=\"toggle-knob\"></div>\r\n                    </div>\r\n                    <span id=\"vendor-open-label\" class=\"status-label\">Store is OPEN</span>\r\n                  </div>\r\n                </div>\r\n              </div>\r\n\r\n              <!-- Quick Jump Cards -->\r\n              <div class=\"vnd-quick-grid\">\r\n                <div class=\"vnd-quick-card\" onclick=\"VendorController.switchSubTab('food')\">\r\n                  <div class=\"vnd-quick-icon\">🍗</div>\r\n                  <div class=\"vnd-quick-text\">\r\n                    <div class=\"vnd-quick-title\">Manage Food</div>\r\n                    <div class=\"vnd-quick-sub\" id=\"vnd-quick-food-count\">0 items on your menu</div>\r\n                  </div>\r\n                  <div class=\"vnd-quick-arrow\">→</div>\r\n                </div>\r\n                <div class=\"vnd-quick-card\" onclick=\"VendorController.switchSubTab('orders')\">\r\n                  <div class=\"vnd-quick-icon\">📋</div>\r\n                  <div class=\"vnd-quick-text\">\r\n                    <div class=\"vnd-quick-title\">Active Orders</div>\r\n                    <div class=\"vnd-quick-sub\" id=\"vnd-quick-orders-count\">0 live orders</div>\r\n                  </div>\r\n                  <div class=\"vnd-quick-arrow\">→</div>\r\n                </div>\r\n              </div>\r\n\r\n              <div class=\"vnd-card\">\r\n                <div class=\"vnd-card-head\">\r\n                  <h3>Store Profile & Hours</h3>\r\n                </div>\r\n                <div class=\"vnd-store-details-wrap\">\r\n                  <p class=\"vnd-muted\" style=\"margin-bottom: 14px;\">Keep your restaurant details and delivery pickup point up to date.</p>\r\n                  <button class=\"vendor-register-link\" onclick=\"VendorController.openRegistrationModal()\">Register New Store +</button>\r\n                </div>\r\n              </div>\r\n            </div>\r\n\r\n          </div>\r\n        </div>\r\n      </section>\r\n\r\n      <!-- -------------------------------------------------------\r\n           ROLE 3: RIDER / DISPATCH PORTAL\r\n           ------------------------------------------------------- -->\r\n      <section id=\"view-rider\" class=\"role-view\">\r\n        <div class=\"rider-dashboard\">\r\n          <div class=\"rider-status-bar\">\r\n            <div class=\"rider-info-group\">\r\n              <img id=\"rider-profile-avatar\" class=\"rider-profile-img\" src=\"\" alt=\"Rider\" />\r\n              <div>\r\n                <h3 id=\"rider-profile-name\" class=\"rider-name-heading\">David Adeleke</h3>\r\n                <div id=\"rider-profile-vehicle\" class=\"rider-vehicle-type\">Bajaj Boxer 150 (LAG-452-IKJ)</div>\r\n              </div>\r\n            </div>\r\n\r\n            <div class=\"rider-online-toggle\">\r\n              <span class=\"radar-pulse-dot\"></span>\r\n              <span>ONLINE & READY</span>\r\n            </div>\r\n          </div>\r\n\r\n          <!-- Rider Earnings Summary -->\r\n          <div class=\"vendor-kpi-grid\">\r\n            <div class=\"kpi-card\">\r\n              <div class=\"kpi-label\">Today's Delivery Earnings</div>\r\n              <div id=\"rider-earnings-val\" class=\"kpi-val\" style=\"color: var(--c-primary);\">₦0</div>\r\n            </div>\r\n            <div class=\"kpi-card\">\r\n              <div class=\"kpi-label\">Completed Deliveries</div>\r\n              <div id=\"rider-trips-count\" class=\"kpi-val\">0</div>\r\n            </div>\r\n            <div class=\"kpi-card\">\r\n              <div class=\"kpi-label\">Rider Rating</div>\r\n              <div class=\"kpi-val\">4.9 ★</div>\r\n            </div>\r\n          </div>\r\n\r\n          <!-- Available Jobs Feed (Shown when not in active mission) -->\r\n          <div id=\"rider-radar-feed-section\" class=\"jobs-feed-container\">\r\n            <div class=\"feed-header-row\">\r\n              <h3 class=\"section-title\">Available Deliveries Near You</h3>\r\n              <span class=\"live-radar-badge\">\r\n                <span class=\"radar-pulse-dot\"></span> Radar Active\r\n              </span>\r\n            </div>\r\n            <div id=\"rider-jobs-feed\">\r\n              <!-- Injected by rider.js -->\r\n            </div>\r\n          </div>\r\n\r\n          <!-- Active Mission Screen (Shown when job accepted) -->\r\n          <div id=\"rider-active-mission-section\" style=\"display: none;\">\r\n            <div class=\"active-mission-card\">\r\n              <div class=\"mission-top-header\">\r\n                <div>\r\n                  <span class=\"mission-live-indicator\">● LIVE MISSION</span>\r\n                  <h3 style=\"font-family: var(--font-display); font-size: 1.25rem; margin: 4px 0 0;\">Active Delivery</h3>\r\n                </div>\r\n                <span id=\"mission-order-id\" class=\"mission-order-badge\"></span>\r\n              </div>\r\n\r\n              <!-- Pickup & Delivery Addresses -->\r\n              <div class=\"mission-stops-card\">\r\n                <!-- Vendor Pickup Stop -->\r\n                <div class=\"mission-stop-block\">\r\n                  <div class=\"mission-stop-icon stop-pickup\">P</div>\r\n                  <div class=\"mission-stop-body\">\r\n                    <div class=\"mission-stop-type\">PICKUP VENDOR</div>\r\n                    <div id=\"mission-store-name\" class=\"mission-stop-name\"></div>\r\n                    <div id=\"mission-store-addr\" class=\"mission-stop-address\"></div>\r\n                    <div class=\"mission-stop-contact\">\r\n                      <a id=\"mission-store-phone-link\" href=\"#\" class=\"mission-contact-btn\">📞 Call Restaurant</a>\r\n                    </div>\r\n                  </div>\r\n                </div>\r\n\r\n                <div class=\"mission-stop-divider\"></div>\r\n\r\n                <!-- Customer Destination Stop -->\r\n                <div class=\"mission-stop-block\">\r\n                  <div class=\"mission-stop-icon stop-dropoff\">D</div>\r\n                  <div class=\"mission-stop-body\">\r\n                    <div class=\"mission-stop-type\">DELIVERY DESTINATION</div>\r\n                    <div id=\"mission-customer-info\" class=\"mission-stop-name\"></div>\r\n                    <div id=\"mission-dropoff-addr\" class=\"mission-stop-address\"></div>\r\n                    <div id=\"mission-delivery-notes-box\" class=\"mission-notes-box\" style=\"display: none;\">\r\n                      <span class=\"notes-icon\">📝</span>\r\n                      <span id=\"mission-delivery-notes-text\"></span>\r\n                    </div>\r\n                    <div class=\"mission-stop-contact\">\r\n                      <a id=\"mission-customer-phone-link\" href=\"#\" class=\"mission-contact-btn\">📞 Call Customer</a>\r\n                    </div>\r\n                  </div>\r\n                </div>\r\n              </div>\r\n\r\n              <!-- What the Person Ordered (Order Manifest) -->\r\n              <div class=\"mission-manifest-card\">\r\n                <div class=\"mission-manifest-header\">\r\n                  <div style=\"display: flex; align-items: center; gap: 8px;\">\r\n                    <span style=\"font-size: 1.1rem;\">🛍️</span>\r\n                    <strong style=\"font-size: 0.95rem;\">Customer Order Details</strong>\r\n                  </div>\r\n                  <span id=\"mission-items-count-badge\" class=\"badge-tag\"></span>\r\n                </div>\r\n                <div id=\"mission-items-manifest-list\" class=\"mission-manifest-list\">\r\n                  <!-- Injected by rider.js -->\r\n                </div>\r\n                <div class=\"mission-manifest-footer\">\r\n                  <span style=\"color: var(--c-text-muted); font-size: 0.82rem;\">Payment: <strong id=\"mission-payment-status\">Paid Online</strong></span>\r\n                  <span style=\"font-size: 0.95rem; font-weight: 800; color: var(--c-primary);\" id=\"mission-total-val\"></span>\r\n                </div>\r\n              </div>\r\n\r\n              <!-- Mapbox Route Map -->\r\n              <div class=\"rider-mission-map\">\r\n                <div id=\"rider-map-canvas\"></div>\r\n              </div>\r\n              <div id=\"rider-mission-stats\" class=\"rider-mission-stats\">\r\n                <div class=\"rider-mission-stat\">\r\n                  <span class=\"rs-label\">Distance</span>\r\n                  <span id=\"mission-distance\" class=\"rs-value\">—</span>\r\n                </div>\r\n                <div class=\"rider-mission-stat\">\r\n                  <span class=\"rs-label\">Est. Time</span>\r\n                  <span id=\"mission-eta\" class=\"rs-value\">—</span>\r\n                </div>\r\n                <div class=\"rider-mission-stat\">\r\n                  <span class=\"rs-label\">Payout</span>\r\n                  <span id=\"mission-payout\" class=\"rs-value\">—</span>\r\n                </div>\r\n              </div>\r\n\r\n              <div id=\"mission-action-container\">\r\n                <!-- Injected dynamically by rider.js based on phase -->\r\n              </div>\r\n            </div>\r\n          </div>\r\n        </div>\r\n      </section>\r\n\r\n      <!-- -------------------------------------------------------\r\n           ROLE 4: ADMIN OPERATIONS CENTER\r\n           ------------------------------------------------------- -->\r\n      <section id=\"view-admin\" class=\"role-view\">\r\n        <div class=\"admin-dashboard\">\r\n          <div class=\"admin-header-row\">\r\n            <div>\r\n              <h2 class=\"admin-title\">Chow45 Operations Command Center</h2>\r\n              <p style=\"font-size: 0.85rem; color: var(--c-text-secondary);\">Real-time platform telemetry across Lagos and Sagamu</p>\r\n            </div>\r\n            <span class=\"admin-badge\">PLATFORM ADMIN</span>\r\n          </div>\r\n\r\n          <!-- Platform KPIs -->\r\n          <div class=\"admin-metrics-grid\">\r\n            <div class=\"admin-stat-card\">\r\n              <div class=\"stat-header\">Total Platform GMV</div>\r\n              <div id=\"admin-kpi-gmv\" class=\"stat-number\">₦0</div>\r\n              <div class=\"stat-sub\">Gross marketplace volume</div>\r\n            </div>\r\n            <div class=\"admin-stat-card fee\">\r\n              <div class=\"stat-header\">₦500 Service Fees Collected</div>\r\n              <div id=\"admin-kpi-fees\" class=\"stat-number\">₦0</div>\r\n              <div class=\"stat-sub\">Direct platform revenue</div>\r\n            </div>\r\n            <div class=\"admin-stat-card accent\">\r\n              <div class=\"stat-header\">Active Orders</div>\r\n              <div id=\"admin-kpi-active-orders\" class=\"stat-number\">0</div>\r\n              <div class=\"stat-sub\">Orders currently in flight</div>\r\n            </div>\r\n            <div class=\"admin-stat-card\">\r\n              <div class=\"stat-header\">Active Restaurants</div>\r\n              <div id=\"admin-kpi-vendors\" class=\"stat-number\">5</div>\r\n              <div class=\"stat-sub\">Verified food spots</div>\r\n            </div>\r\n          </div>\r\n\r\n          <!-- Split View: Orders Radar & Vendor Approvals -->\r\n          <div class=\"admin-split-view\">\r\n            <!-- Platform Orders Table -->\r\n            <div class=\"admin-card\">\r\n              <div class=\"admin-card-title\">\r\n                <span>Real-Time Orders Radar</span>\r\n                <input type=\"text\" id=\"admin-order-search\" placeholder=\"Search order ID, store, customer...\" style=\"font-size: 0.78rem; padding: 4px 10px; border-radius: var(--radius-pill); border: 1px solid var(--c-border); width: 200px;\" />\r\n              </div>\r\n              <div class=\"data-table-wrap\">\r\n                <table class=\"admin-table\">\r\n                  <thead>\r\n                    <tr>\r\n                      <th>Order ID</th>\r\n                      <th>Customer</th>\r\n                      <th>Store</th>\r\n                      <th>Total</th>\r\n                      <th>Status</th>\r\n                      <th>Rider</th>\r\n                    </tr>\r\n                  </thead>\r\n                  <tbody id=\"admin-orders-tbody\">\r\n                    <!-- Injected by admin.js -->\r\n                  </tbody>\r\n                </table>\r\n              </div>\r\n            </div>\r\n\r\n            <!-- Pending Vendor Applications & Disputes -->\r\n            <div style=\"display: flex; flex-direction: column; gap: var(--space-20);\">\r\n              <div class=\"admin-card\">\r\n                <div class=\"admin-card-title\">\r\n                  <span>Vendor Verification Pipeline</span>\r\n                </div>\r\n                <div id=\"admin-pending-vendors-list\">\r\n                  <!-- Injected by admin.js -->\r\n                </div>\r\n              </div>\r\n\r\n              <div class=\"admin-card\">\r\n                <div class=\"admin-card-title\">\r\n                  <span>Customer Disputes & Refunds</span>\r\n                </div>\r\n                <div id=\"admin-disputes-list\">\r\n                  <!-- Injected by admin.js -->\r\n                </div>\r\n              </div>\r\n            </div>\r\n          </div>\r\n\r\n          <!-- Service Areas Manager -->\r\n          <div class=\"admin-card\">\r\n            <div class=\"admin-card-title\">\r\n              <span>Service Areas & Delivery Zones</span>\r\n              <small style=\"font-size: 0.8rem; font-weight: 500; color: var(--c-text-muted);\">Coordinate-based availability; draw / move polygon pins on the map below</small>\r\n            </div>\r\n            <div id=\"admin-zones-list\">\r\n              <!-- Injected by admin.js -->\r\n            </div>\r\n          </div>\r\n\r\n          <!-- Delivery Fee Configuration -->\r\n          <div class=\"admin-card\">\r\n            <div class=\"admin-card-title\"><span>Delivery Fee Configuration</span></div>\r\n            <div id=\"admin-fee-config\">\r\n              <!-- Injected by admin.js -->\r\n            </div>\r\n          </div>\r\n\r\n          <!-- Operations Map -->\r\n          <div class=\"admin-card\">\r\n            <div class=\"admin-card-title\">\r\n              <span>Operations Map</span>\r\n              <small style=\"font-size: 0.8rem; font-weight: 500; color: var(--c-text-muted);\">Active vendors, riders, orders & service zones</small>\r\n            </div>\r\n            <div class=\"admin-map-wrap\">\r\n              <div id=\"admin-map-canvas\"></div>\r\n            </div>\r\n          </div>\r\n        </div>\r\n      </section>\r\n    </main>\r\n\r\n    <!-- =========================================================\r\n         MOBILE FLOATING BOTTOM NAVIGATION BAR\r\n         ========================================================= -->\r\n    <nav class=\"bottom-nav\" data-nav-for=\"customer\" aria-label=\"Mobile Navigation\">\r\n      <button class=\"bottom-tab active\" data-role=\"customer\" onclick=\"Chow45App.switchRole('customer')\">\r\n        <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><path d=\"M3 9l9-7 9 7v11a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2z\"/><polyline points=\"9 22 9 12 15 12 15 22\"/></svg>\r\n        <span>Discover</span>\r\n      </button>\r\n\r\n      <button class=\"bottom-tab\" onclick=\"CustomerController.openOrderHistory()\">\r\n        <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><path d=\"M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z\"/><polyline points=\"14 2 14 8 20 8\"/></svg>\r\n        <span>Orders</span>\r\n      </button>\r\n\r\n      <button class=\"bottom-tab\" onclick=\"CustomerController.openCart()\">\r\n        <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><circle cx=\"9\" cy=\"21\" r=\"1\"/><circle cx=\"20\" cy=\"21\" r=\"1\"/><path d=\"M1 1h4l2.68 13.39a2 2 0 0 0 2 1.61h9.72a2 2 0 0 0 2-1.61L23 6H6\"/></svg>\r\n        <span>Cart</span>\r\n        <span class=\"tab-badge cart-badge-count\" style=\"display: none;\">0</span>\r\n      </button>\r\n    </nav>\r\n\r\n    <!-- Vendors manage a menu, not a storefront, so they get their own bar. -->\r\n    <nav class=\"bottom-nav\" data-nav-for=\"vendor\" aria-label=\"Vendor Navigation\" hidden>\r\n      <button class=\"bottom-tab active\" data-vendor-tab=\"food\" onclick=\"VendorController.switchSubTab('food')\">\r\n        <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><path d=\"M3 2v7c0 1.1.9 2 2 2h4a2 2 0 0 0 2-2V2\"/><path d=\"M7 2v20\"/><path d=\"M21 15V2a5 5 0 0 0-5 5v6a2 2 0 0 0 2 2h3zm0 0v7\"/></svg>\r\n        <span>Foods</span>\r\n      </button>\r\n\r\n      <button class=\"bottom-tab\" data-vendor-tab=\"orders\" onclick=\"VendorController.switchSubTab('orders')\">\r\n        <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><path d=\"M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z\"/><polyline points=\"14 2 14 8 20 8\"/></svg>\r\n        <span>Active orders</span>\r\n        <span class=\"tab-badge vendor-orders-badge-count\" style=\"display: none;\">0</span>\r\n      </button>\r\n\r\n      <button class=\"bottom-tab\" data-vendor-tab=\"store\" onclick=\"VendorController.switchSubTab('store')\">\r\n        <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><path d=\"M3 9l1.5-5h15L21 9\"/><path d=\"M4 9v11a1 1 0 0 0 1 1h14a1 1 0 0 0 1-1V9\"/><path d=\"M9 21v-6h6v6\"/></svg>\r\n        <span>Store</span>\r\n      </button>\r\n\r\n      <button class=\"bottom-tab\" data-vendor-tab=\"money\" onclick=\"VendorController.switchSubTab('money')\">\r\n        <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><circle cx=\"12\" cy=\"12\" r=\"9\"/><path d=\"M15 9.5a3 3 0 0 0-3-1.5c-1.7 0-3 .8-3 2s1.3 2 3 2 3 .8 3 2-1.3 2-3 2a3 3 0 0 1-3-1.5\"/><path d=\"M12 6.5v11\"/></svg>\r\n        <span>Earnings</span>\r\n      </button>\r\n    </nav>\r\n\r\n    <!-- =========================================================\r\n         MODALS & SHEETS\r\n         ========================================================= -->\r\n\r\n    <!-- Modal 1: Food Customization Sheet (Point 8) -->\r\n    <div id=\"custom-dish-modal\" class=\"modal-backdrop\">\r\n      <div class=\"modal-sheet\">\r\n        <div class=\"modal-header\">\r\n          <div>\r\n            <div class=\"modal-title\" id=\"custom-dish-title\">Jollof Rice</div>\r\n            <small id=\"custom-dish-store\" style=\"font-size: 0.78rem; color: var(--c-text-muted); font-weight: 600;\"></small>\r\n          </div>\r\n          <button class=\"modal-close-btn\" onclick=\"CustomerController.closeDishCustomizer()\">✕</button>\r\n        </div>\r\n        <div class=\"modal-body\">\r\n          <img id=\"custom-dish-banner\" class=\"custom-dish-banner\" src=\"\" alt=\"Dish\" />\r\n          <p id=\"custom-dish-desc\" style=\"font-size: 0.85rem; color: var(--c-text-secondary); margin-bottom: var(--space-12);\"></p>\r\n\r\n          <!-- Portion Selector (Per Scoop vs Per Plate when Both exist) -->\r\n          <div id=\"custom-portion-select-wrap\" style=\"display: none; margin-bottom: 16px;\">\r\n            <label style=\"display: block; font-weight: 700; font-size: 0.88rem; color: #111827; margin-bottom: 8px;\">How would you like it served?</label>\r\n            <div class=\"custom-portion-grid\">\r\n              <div id=\"custom-portion-scoop\" class=\"custom-portion-card\" onclick=\"CustomerController.selectCustomPortion('SCOOP')\">\r\n                <div style=\"font-size: 1.3rem;\">🥄</div>\r\n                <div style=\"font-weight: 700; font-size: 0.88rem; margin: 2px 0;\">Per Scoop</div>\r\n                <div id=\"custom-portion-scoop-price\" style=\"font-size: 0.85rem; color: #0C513F; font-weight: 800;\">₦500</div>\r\n              </div>\r\n              <div id=\"custom-portion-plate\" class=\"custom-portion-card selected\" onclick=\"CustomerController.selectCustomPortion('PLATE')\">\r\n                <div style=\"font-size: 1.3rem;\">🍽️</div>\r\n                <div style=\"font-weight: 700; font-size: 0.88rem; margin: 2px 0;\">Per Plate</div>\r\n                <div id=\"custom-portion-plate-price\" style=\"font-size: 0.85rem; color: #0C513F; font-weight: 800;\">₦2,000</div>\r\n              </div>\r\n            </div>\r\n          </div>\r\n\r\n          <!-- Single Portion Tag (when only scoop or only plate) -->\r\n          <div id=\"custom-portion-single-wrap\" style=\"display: none; margin-bottom: 14px;\">\r\n            <div id=\"custom-portion-single-badge\" style=\"display: inline-flex; align-items: center; gap: 6px; background: #E8F6F0; color: #0C513F; font-weight: 700; font-size: 0.85rem; padding: 6px 14px; border-radius: 999px;\"></div>\r\n          </div>\r\n\r\n          <!-- Size Selector (per-piece items that come in sizes) -->\r\n          <div id=\"custom-size-select-wrap\" style=\"display: none; margin-bottom: 16px;\">\r\n            <label style=\"display: block; font-weight: 700; font-size: 0.88rem; color: #111827; margin-bottom: 8px;\">\r\n              Choose a size <span class=\"custom-required-tag\">Required</span>\r\n            </label>\r\n            <div class=\"custom-size-grid\" id=\"custom-size-grid\" role=\"radiogroup\" aria-label=\"Choose a size\"></div>\r\n          </div>\r\n\r\n          <div id=\"custom-addons-container\">\r\n            <!-- Addon options injected dynamically -->\r\n          </div>\r\n\r\n          <div style=\"display: flex; align-items: center; justify-content: space-between; margin-top: var(--space-16); padding-top: 14px; border-top: 1px solid var(--c-border-subtle);\">\r\n            <div>\r\n              <span style=\"font-weight: 700; font-size: 0.95rem; display: block; color: #111827;\">Quantity</span>\r\n              <span id=\"custom-dish-qty-sub\" style=\"font-size: 0.78rem; color: var(--c-text-muted);\">1 plate</span>\r\n            </div>\r\n            <div class=\"qty-control\">\r\n              <button class=\"qty-btn\" onclick=\"CustomerController.changeCustomQty(-1)\">−</button>\r\n              <span id=\"custom-dish-qty\" class=\"qty-display\">1</span>\r\n              <button class=\"qty-btn\" onclick=\"CustomerController.changeCustomQty(1)\">+</button>\r\n            </div>\r\n          </div>\r\n        </div>\r\n        <div class=\"modal-footer\">\r\n          <button id=\"custom-add-to-cart-btn\" class=\"cta-primary-btn\" onclick=\"CustomerController.confirmAddToCart()\">\r\n            Add to Cart\r\n          </button>\r\n        </div>\r\n      </div>\r\n    </div>\r\n\r\n    <!-- Modal 2: Single-Store Conflict Warning Modal (Point 9) -->\r\n    <div id=\"cart-conflict-modal\" class=\"modal-backdrop\">\r\n      <div class=\"modal-sheet\" style=\"max-width: 440px;\">\r\n        <div class=\"conflict-card\">\r\n          <div class=\"conflict-icon-wrap\">\r\n            <svg width=\"32\" height=\"32\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.2\"><path d=\"M10.29 3.86L1.82 18a2 2 0 0 0 1.71 3h16.94a2 2 0 0 0 1.71-3L13.71 3.86a2 2 0 0 0-3.42 0z\"/><line x1=\"12\" y1=\"9\" x2=\"12\" y2=\"13\"/><line x1=\"12\" y1=\"17\" x2=\"12.01\" y2=\"17\"/></svg>\r\n          </div>\r\n          <h3 class=\"conflict-title\">Start a new order?</h3>\r\n          <p class=\"conflict-text\">\r\n            Your cart contains items from <strong id=\"conflict-existing-store\"></strong>.<br />\r\n            Starting a new order will remove your current cart.\r\n          </p>\r\n          <div class=\"conflict-btn-group\">\r\n            <button id=\"conflict-confirm-clear-btn\" class=\"cta-primary-btn\" style=\"background: #DC2626;\">\r\n              Start New Order\r\n            </button>\r\n            <button id=\"conflict-cancel-btn\" class=\"action-btn-secondary\" style=\"width: 100%;\">\r\n              Keep Current Order\r\n            </button>\r\n          </div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n\r\n    <!-- Modal 3: Shopping Cart & Transparent Checkout Sheet (Point 21 & 56) -->\r\n    <div id=\"cart-modal\" class=\"modal-backdrop\">\r\n      <div class=\"modal-sheet\">\r\n        <div class=\"modal-header\">\r\n          <div>\r\n            <div class=\"modal-title\">Your Chow45 Order</div>\r\n            <small id=\"cart-store-header-name\" style=\"font-size: 0.75rem; color: var(--c-text-muted); font-weight: 600; display: block;\"></small>\r\n          </div>\r\n          <button class=\"modal-close-btn\" onclick=\"CustomerController.closeCart()\">✕</button>\r\n        </div>\r\n\r\n        <div class=\"modal-body\">\r\n          <div id=\"cart-items-list\">\r\n            <!-- Injected by customer.js -->\r\n          </div>\r\n\r\n          <div id=\"cart-checkout-footer\" style=\"display: none; margin-top: var(--space-20);\">\r\n            <!-- Transparent Breakdown (Point 21) -->\r\n            <div class=\"checkout-summary-box\">\r\n              <div class=\"price-row\">\r\n                <span>Food subtotal</span>\r\n                <span id=\"cart-subtotal-val\">₦0</span>\r\n              </div>\r\n              <div class=\"price-row service-fee-row\">\r\n                <span>Service fee <span class=\"service-fee-badge\">Mandatory</span></span>\r\n                <span id=\"cart-service-fee-val\">₦500</span>\r\n              </div>\r\n              <div class=\"price-row\">\r\n                <span>Delivery fee</span>\r\n                <span id=\"cart-delivery-fee-val\">₦800</span>\r\n              </div>\r\n              <div id=\"cart-delivery-quote\" class=\"delivery-quote-row\" style=\"display: none;\"></div>\r\n              <div class=\"price-row total-row\">\r\n                <span>TOTAL</span>\r\n                <span id=\"cart-grand-total-val\" style=\"color: var(--c-primary);\">₦0</span>\r\n              </div>\r\n            </div>\r\n\r\n            <!-- Delivery Details -->\r\n            <div class=\"checkout-input-group\">\r\n              <div style=\"display: flex; justify-content: space-between; align-items: center; margin-bottom: 6px;\">\r\n                <label class=\"checkout-label\" style=\"margin-bottom: 0;\">DELIVER TO</label>\r\n                <button type=\"button\" style=\"border: none; background: transparent; color: var(--c-primary); font-size: 0.78rem; font-weight: 700; cursor: pointer;\" onclick=\"Chow45App.openLocationModal()\">Change</button>\r\n              </div>\r\n              <input type=\"text\" id=\"checkout-address-input\" class=\"checkout-input\" value=\"9 Goshen Ave, Idimu, Lagos\" />\r\n            </div>\r\n\r\n            <div style=\"display: grid; grid-template-columns: 1fr 1fr; gap: var(--space-12);\">\r\n              <div class=\"checkout-input-group\">\r\n                <label class=\"checkout-label\">Recipient Name</label>\r\n                <input type=\"text\" id=\"checkout-name-input\" class=\"checkout-input\" value=\"Precious M.\" />\r\n              </div>\r\n              <div class=\"checkout-input-group\">\r\n                <label class=\"checkout-label\">Phone Number</label>\r\n                <input type=\"text\" id=\"checkout-phone-input\" class=\"checkout-input\" value=\"+234 812 450 4500\" />\r\n              </div>\r\n            </div>\r\n\r\n            <div class=\"checkout-input-group\">\r\n              <label class=\"checkout-label\">Delivery Note / Flat No.</label>\r\n              <input type=\"text\" id=\"checkout-notes-input\" class=\"checkout-input\" placeholder=\"e.g. Call when outside gate\" />\r\n            </div>\r\n\r\n            <div class=\"checkout-input-group\">\r\n              <label class=\"checkout-label\">Payment Option</label>\r\n              <select id=\"checkout-payment-method\" class=\"checkout-select\">\r\n                <option value=\"Card (Paystack)\">Debit Card (Paystack Instant)</option>\r\n                <option value=\"Bank Transfer\">Direct Bank Transfer</option>\r\n                <option value=\"Cash on Delivery\">Cash on Delivery</option>\r\n              </select>\r\n            </div>\r\n\r\n            <button id=\"cart-pay-cta-btn\" class=\"cta-primary-btn\" style=\"margin-top: var(--space-16);\" onclick=\"CustomerController.placeOrder()\">\r\n              Pay & Place Order\r\n            </button>\r\n          </div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n\r\n    <!-- Modal 4: Location Selector Modal (Point 14 & 15) -->\r\n    <div id=\"location-modal\" class=\"modal-backdrop\">\r\n      <div class=\"modal-sheet\" style=\"max-width: 480px;\">\r\n        <div class=\"modal-header\">\r\n          <div class=\"modal-title\">Where should we deliver your food?</div>\r\n          <button class=\"modal-close-btn\" onclick=\"document.getElementById('location-modal').classList.remove('open')\">✕</button>\r\n        </div>\r\n        <div class=\"modal-body\">\r\n          <div style=\"display: flex; gap: 8px; margin-bottom: 14px;\">\r\n            <button class=\"cta-primary-btn\" style=\"padding: 8px 12px; font-size: 0.8rem; background: var(--c-primary-surface); color: var(--c-primary); border: 1px solid var(--c-primary);\" onclick=\"window.chowApp.toast('Location pinned: 9 Goshen Ave, Idimu, Lagos', 'success'); document.getElementById('location-modal').classList.remove('open');\">\r\n              📍 Use my current location\r\n            </button>\r\n          </div>\r\n          <p style=\"font-size: 0.8rem; color: var(--c-text-secondary); margin-bottom: 8px; font-weight: 700;\">SAVED ADDRESSES & POPULAR ZONES:</p>\r\n          <div id=\"location-options-list\">\r\n            <!-- Injected by app.js -->\r\n          </div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n\r\n    <!-- Modal 4b: Full-Screen Mapbox Location Picker (Point 3-15) -->\r\n    <div id=\"map-picker-modal\" class=\"map-picker-modal\">\r\n      <div class=\"map-picker-shell\">\r\n        <!-- Header / Search -->\r\n        <header class=\"picker-header\">\r\n          <button id=\"picker-back-btn\" class=\"picker-back-btn\" aria-label=\"Back\" onclick=\"Chow45LocationPicker.close()\">\r\n            <svg width=\"18\" height=\"18\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"19\" y1=\"12\" x2=\"5\" y2=\"12\"/><polyline points=\"12 19 5 12 12 5\"/></svg>\r\n          </button>\r\n          <div class=\"picker-title\">Choose delivery location</div>\r\n          <div class=\"picker-search-wrap\">\r\n            <svg width=\"17\" height=\"17\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.4\"><circle cx=\"11\" cy=\"11\" r=\"8\"/><line x1=\"21\" y1=\"21\" x2=\"16.65\" y2=\"16.65\"/></svg>\r\n            <input id=\"picker-search-input\" type=\"text\" class=\"picker-search-input\" placeholder=\"Search for an address\" autocomplete=\"off\" spellcheck=\"false\" />\r\n          </div>\r\n        </header>\r\n\r\n        <!-- Search results & saved addresses -->\r\n        <div id=\"picker-search-results\" class=\"picker-search-results\"></div>\r\n        <div id=\"picker-saved-addresses\" class=\"picker-saved-addresses\"></div>\r\n\r\n        <!-- Map with centered movable pin -->\r\n        <div class=\"picker-map-stage\">\r\n          <div id=\"picker-map-canvas\"></div>\r\n          <div id=\"picker-center-pin\" class=\"picker-center-pin\" aria-hidden=\"true\"></div>\r\n          <div class=\"picker-float-controls\">\r\n            <button id=\"picker-gps-btn\" class=\"picker-map-btn primary\">\r\n              <svg width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.4\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><circle cx=\"12\" cy=\"12\" r=\"4\"/></svg>\r\n              Use my current location\r\n            </button>\r\n            <button id=\"picker-search-area-btn\" class=\"picker-map-btn\">\r\n              <svg width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.4\"><search/><path d=\"M21 10c0 7-9 13-9 13s-9-6-9-13a9 9 0 0 1 18 0z\"/><circle cx=\"12\" cy=\"10\" r=\"3\"/></svg>\r\n              Search this area\r\n            </button>\r\n          </div>\r\n          <button id=\"picker-gps-fab\" class=\"picker-gps-fab\" aria-label=\"Use my current location\" onclick=\"Chow45LocationPicker.useCurrentLocation()\">\r\n            <svg width=\"24\" height=\"24\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.4\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><circle cx=\"12\" cy=\"12\" r=\"4\"/></svg>\r\n          </button>\r\n        </div>\r\n\r\n        <!-- Availability status banner -->\r\n        <div id=\"picker-status-banner\" class=\"picker-status-banner\"></div>\r\n\r\n        <!-- Streamlined Floating Confirmation Bar -->\r\n        <footer id=\"picker-confirm-card\" class=\"picker-confirm-card\" style=\"padding: 14px 20px calc(14px + env(safe-area-inset-bottom, 0px)); background: #FFFFFF; box-shadow: 0 -8px 24px rgba(0,0,0,0.12); border-top: 1px solid var(--c-border-subtle, #E6DEC8); display: flex; align-items: center; justify-content: space-between; gap: 14px; z-index: 30;\">\r\n          <div style=\"display: flex; align-items: center; gap: 12px; min-width: 0; flex: 1;\">\r\n            <div class=\"picker-check-icon\" style=\"width: 38px; height: 38px; min-width: 38px; border-radius: 50%; background: #E8F6F0; color: #0C513F; display: flex; align-items: center; justify-content: center; font-size: 1.2rem;\">\r\n              📍\r\n            </div>\r\n            <div style=\"min-width: 0; flex: 1;\">\r\n              <div id=\"picker-address-text\" class=\"picker-address-text\" style=\"font-size: 0.94rem; font-weight: 700; color: #111827; white-space: nowrap; overflow: hidden; text-overflow: ellipsis;\">\r\n                Selecting location...\r\n              </div>\r\n              <div id=\"picker-zone-status\" class=\"picker-zone-status ok\" style=\"font-size: 0.78rem; color: #0C513F; font-weight: 600; white-space: nowrap; overflow: hidden; text-overflow: ellipsis;\">\r\n                Ready to confirm\r\n              </div>\r\n            </div>\r\n          </div>\r\n\r\n          <button type=\"button\" id=\"picker-confirm-btn\" class=\"cta-primary-btn picker-confirm-btn\" onclick=\"Chow45LocationPicker.confirmLocation()\" style=\"flex-shrink: 0; padding: 13px 24px; border-radius: 12px; font-weight: 800; font-size: 0.95rem; width: auto; min-width: 160px; cursor: pointer; background: #0C513F; color: #FFFFFF;\">\r\n            Confirm Location ✓\r\n          </button>\r\n        </footer>\r\n      </div>\r\n    </div>\r\n\r\n    <!-- Modal 4c: Input & Save Location Modal (Campus / Home / Work) -->\r\n    <div id=\"save-place-modal\" class=\"modal-backdrop\" style=\"z-index: 300;\" onclick=\"if(event.target === this) Chow45LocationPicker.closeSavePlaceModal()\">\r\n      <div class=\"modal-sheet\" style=\"max-width: 480px; width: 92%; border-radius: 20px; overflow: hidden; box-shadow: 0 20px 40px rgba(0,0,0,0.25);\">\r\n        <div class=\"modal-header\" style=\"display: flex; align-items: center; justify-content: space-between; padding: 16px 20px; border-bottom: 1px solid var(--c-border-subtle, #EFECE6); background: #FAF9F5;\">\r\n          <div style=\"display: flex; align-items: center; gap: 12px;\">\r\n            <button type=\"button\" class=\"modal-back-btn\" onclick=\"Chow45LocationPicker.closeSavePlaceModal()\" aria-label=\"Back\" title=\"Back\" style=\"border: none; background: #E8E5DD; width: 38px; height: 38px; border-radius: 50%; display: flex; align-items: center; justify-content: center; cursor: pointer; color: #111111; transition: background 0.15s ease;\">\r\n              <svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.6\"><line x1=\"19\" y1=\"12\" x2=\"5\" y2=\"12\"/><polyline points=\"12 19 5 12 12 5\"/></svg>\r\n            </button>\r\n            <div>\r\n              <div class=\"modal-title\" id=\"save-place-modal-title\" style=\"font-size: 1.1rem; font-weight: 800; color: #111827;\">Set Location Address</div>\r\n              <small id=\"save-place-modal-subtitle\" style=\"font-size: 0.78rem; color: #6E6D66; font-weight: 600; display: block;\">Save place for quick one-tap orders</small>\r\n            </div>\r\n          </div>\r\n          <button type=\"button\" class=\"modal-close-btn\" onclick=\"Chow45LocationPicker.closeSavePlaceModal()\" aria-label=\"Close\" style=\"border: none; background: none; font-size: 1.2rem; cursor: pointer; color: #6E6D66; padding: 4px 8px;\">✕</button>\r\n        </div>\r\n\r\n        <div class=\"modal-body\" style=\"padding: 20px 22px;\">\r\n          <!-- Slot Badge banner -->\r\n          <div id=\"save-place-slot-banner\" style=\"display: flex; align-items: center; gap: 12px; background: #FAF6EB; padding: 12px 16px; border-radius: 12px; margin-bottom: 16px; border: 1px solid rgba(12,81,63,0.18);\">\r\n            <span id=\"save-place-slot-icon\" style=\"font-size: 1.8rem;\">🏫</span>\r\n            <div style=\"flex: 1; min-width: 0;\">\r\n              <strong id=\"save-place-slot-name\" style=\"display: block; font-size: 0.95rem; color: #0C513F;\">Campus Address</strong>\r\n              <small id=\"save-place-slot-hint\" style=\"font-size: 0.8rem; color: #6E6D66;\">e.g. OOU Main Campus Gate, Ago-Iwoye</small>\r\n            </div>\r\n          </div>\r\n\r\n          <form onsubmit=\"event.preventDefault(); Chow45LocationPicker.confirmSavePlace();\">\r\n            <!-- Address input -->\r\n            <div class=\"checkout-input-group\" style=\"margin-bottom: 14px;\">\r\n              <div style=\"display: flex; justify-content: space-between; align-items: center; margin-bottom: 6px;\">\r\n                <label class=\"checkout-label\" for=\"save-place-address-input\" style=\"font-weight: 700; font-size: 0.85rem; color: #1F2937;\">Address / Campus Landmark</label>\r\n                <button type=\"button\" onclick=\"Chow45LocationPicker.useCurrentLocationForSavePlace()\" style=\"background: none; border: none; font-size: 0.78rem; font-weight: 700; color: #0C513F; cursor: pointer; display: flex; align-items: center; gap: 4px;\">\r\n                  📍 <span>Use GPS location</span>\r\n                </button>\r\n              </div>\r\n              <div class=\"auth-input-wrap\">\r\n                <span class=\"auth-input-icon\">📍</span>\r\n                <input type=\"text\" id=\"save-place-address-input\" class=\"checkout-input auth-input\" placeholder=\"Type address or campus landmark...\" required autocomplete=\"street-address\" autofocus />\r\n              </div>\r\n            </div>\r\n\r\n            <!-- Quick Suggestions for One-Tap Fill -->\r\n            <div style=\"margin-bottom: 16px;\">\r\n              <span style=\"font-size: 0.74rem; font-weight: 800; color: #6E6D66; text-transform: uppercase; letter-spacing: 0.5px; display: block; margin-bottom: 8px;\">Popular Suggestions (Tap to fill)</span>\r\n              <div id=\"save-place-suggestions\" style=\"display: flex; flex-wrap: wrap; gap: 6px;\">\r\n                <!-- Injected dynamically based on slot -->\r\n              </div>\r\n            </div>\r\n\r\n            <!-- Optional Delivery Notes / Room / Office -->\r\n            <div class=\"checkout-input-group\" style=\"margin-bottom: 20px;\">\r\n              <label class=\"checkout-label\" for=\"save-place-note-input\" style=\"font-weight: 700; font-size: 0.85rem; color: #1F2937;\">\r\n                Hostel / Room / Landmark Note <small style=\"color: #6E6D66; font-weight: 400;\">(Optional)</small>\r\n              </label>\r\n              <div class=\"auth-input-wrap\">\r\n                <span class=\"auth-input-icon\">📝</span>\r\n                <input type=\"text\" id=\"save-place-note-input\" class=\"checkout-input auth-input\" placeholder=\"e.g. Block B, Room 14 or beside Library\" />\r\n              </div>\r\n            </div>\r\n\r\n            <!-- Action buttons: Cancel & Save -->\r\n            <div style=\"display: flex; gap: 10px; margin-top: 10px;\">\r\n              <button type=\"button\" class=\"modal-cancel-btn\" onclick=\"Chow45LocationPicker.closeSavePlaceModal()\" style=\"flex: 1; padding: 13px 16px; border-radius: 12px; border: 1.5px solid #E6DEC8; background: #FAF6EB; color: #383834; font-weight: 700; font-size: 0.92rem; cursor: pointer; transition: background 0.15s ease;\">\r\n                Cancel\r\n              </button>\r\n              <button type=\"submit\" id=\"save-place-confirm-btn\" class=\"cta-primary-btn\" style=\"flex: 1.6; padding: 13px 18px; border-radius: 12px; font-weight: 800; font-size: 0.92rem; cursor: pointer;\">\r\n                Save Address ✓\r\n              </button>\r\n            </div>\r\n          </form>\r\n        </div>\r\n      </div>\r\n    </div>\r\n\r\n    <!-- Modal 5: Guided 4-Step Vendor Onboarding Wizard -->\r\n    <div id=\"vendor-register-modal\" class=\"modal-backdrop\">\r\n      <div class=\"modal-sheet\" style=\"max-width: 520px;\">\r\n        <div class=\"modal-header\">\r\n          <div>\r\n            <div class=\"modal-title\">Open Your Restaurant</div>\r\n            <small id=\"v-reg-indicator\" style=\"color: var(--c-text-muted); font-size: 0.78rem; font-weight: 700;\">Step 1 of 4</small>\r\n          </div>\r\n          <button class=\"modal-close-btn\" onclick=\"VendorController.closeRegistrationModal()\">✕</button>\r\n        </div>\r\n\r\n        <div class=\"modal-body\">\r\n          <!-- Step 1: Account -->\r\n          <div id=\"v-reg-step-1\" class=\"vnd-step\">\r\n            <h4 class=\"vnd-step-title\">Step 1 · Create Vendor Account</h4>\r\n            <div class=\"checkout-input-group\">\r\n              <label class=\"checkout-label\">Owner Full Name</label>\r\n              <input type=\"text\" id=\"v-reg-owner-name\" class=\"checkout-input vnd-input\" placeholder=\"e.g. Tolani Adeleke\" />\r\n            </div>\r\n            <div class=\"checkout-input-group\">\r\n              <label class=\"checkout-label\">Contact Phone</label>\r\n              <input type=\"text\" id=\"v-reg-phone\" class=\"checkout-input vnd-input\" placeholder=\"+234 800 000 0000\" />\r\n            </div>\r\n            <div class=\"checkout-input-group\">\r\n              <label class=\"checkout-label\">Email Address</label>\r\n              <input type=\"email\" id=\"v-reg-email\" class=\"checkout-input vnd-input\" placeholder=\"you@example.com\" />\r\n            </div>\r\n            <div class=\"checkout-input-group\">\r\n              <label class=\"checkout-label\">Your Password</label>\r\n              <input type=\"password\" id=\"v-reg-password\" class=\"checkout-input vnd-input\" placeholder=\"Create a password\" />\r\n            </div>\r\n            <button class=\"cta-primary-btn vnd-btn-big\" onclick=\"VendorController.setRegStep(2)\">Next: Your Store →</button>\r\n          </div>\r\n\r\n          <!-- Step 2: Store Identity -->\r\n          <div id=\"v-reg-step-2\" class=\"vnd-step\" style=\"display: none;\">\r\n            <h4 class=\"vnd-step-title\">Step 2 · Your Store</h4>\r\n            <div class=\"checkout-input-group\">\r\n              <label class=\"checkout-label\">Store Name</label>\r\n              <input type=\"text\" id=\"v-reg-store-name\" class=\"checkout-input vnd-input\" placeholder=\"e.g. Sagamu Special Kitchen\" />\r\n            </div>\r\n            <div class=\"checkout-input-group\">\r\n              <label class=\"checkout-label\">Cuisine Specialty</label>\r\n              <input type=\"text\" id=\"v-reg-cuisine\" class=\"checkout-input vnd-input\" placeholder=\"e.g. Jollof Rice, Swallows, Suya\" />\r\n            </div>\r\n            <div class=\"checkout-input-group\">\r\n              <label class=\"checkout-label\">Store Phone</label>\r\n              <input type=\"text\" id=\"v-reg-store-phone\" class=\"checkout-input vnd-input\" placeholder=\"+234 800 111 1111\" />\r\n            </div>\r\n            <div class=\"checkout-input-group\">\r\n              <label class=\"checkout-label\">Pickup Address</label>\r\n              <div class=\"vnd-pickup-field\">\r\n                <input type=\"text\" id=\"v-reg-address\" class=\"checkout-input vnd-input vnd-pickup-input\" readonly\r\n                       placeholder=\"Tap to pick your pickup point on the map\"\r\n                       onclick=\"VendorController.pickPickupAddress()\" />\r\n                <button type=\"button\" class=\"vnd-pickup-map-btn\" onclick=\"VendorController.pickPickupAddress()\" title=\"Pick on map\">📍</button>\r\n              </div>\r\n              <button type=\"button\" class=\"vnd-btn vnd-btn-secondary vnd-btn-big vnd-gps-btn\" onclick=\"VendorController.useCurrentLocationAsPickup()\">\r\n                📍 Use My Current Location\r\n              </button>\r\n              <div class=\"vnd-pickup-hint\" id=\"vnd-pickup-hint\">Tap the address to open the map, or use your current location.</div>\r\n            </div>\r\n            <div class=\"checkout-input-group\">\r\n              <label class=\"checkout-label\">Local Government Area (LGA)</label>\r\n              <select id=\"v-reg-lga\" class=\"checkout-input vnd-input\">\r\n                <option value=\"Alimosho LGA\">Alimosho LGA (Idimu, Egbeda)</option>\r\n                <option value=\"Ikeja LGA\">Ikeja LGA</option>\r\n                <option value=\"Lagos Mainland LGA\">Lagos Mainland (Yaba)</option>\r\n                <option value=\"Surulere LGA\">Surulere LGA</option>\r\n                <option value=\"Eti-Osa LGA\">Eti-Osa LGA (Lekki)</option>\r\n                <option value=\"Sagamu LGA\">Sagamu LGA (OOU Campus)</option>\r\n              </select>\r\n            </div>\r\n\r\n            <div class=\"vnd-time-row\">\r\n              <div class=\"vnd-time-col\">\r\n                <label>Opening Time</label>\r\n                <div class=\"vnd-time-selects\">\r\n                  <select id=\"v-reg-open-hour\" class=\"vnd-time-select\">\r\n                    <option>7</option><option>8</option><option>9</option><option>10</option><option>11</option><option>12</option><option>1</option><option>2</option><option>3</option><option>4</option><option>5</option><option>6</option>\r\n                  </select>\r\n                  <select id=\"v-reg-open-min\" class=\"vnd-time-select\"><option>00</option><option>30</option></select>\r\n                  <select id=\"v-reg-open-ampm\" class=\"vnd-time-select\"><option>AM</option><option>PM</option></select>\r\n                </div>\r\n              </div>\r\n              <div class=\"vnd-time-col\">\r\n                <label>Closing Time</label>\r\n                <div class=\"vnd-time-selects\">\r\n                  <select id=\"v-reg-close-hour\" class=\"vnd-time-select\">\r\n                    <option>7</option><option>8</option><option>9</option><option selected>9</option><option>10</option><option>11</option><option>12</option><option>1</option><option>6</option><option>2</option><option>3</option><option>4</option><option>5</option><option>6</option>\r\n                  </select>\r\n                  <select id=\"v-reg-close-min\" class=\"vnd-time-select\"><option>00</option><option>30</option></select>\r\n                  <select id=\"v-reg-close-ampm\" class=\"vnd-time-select\"><option>AM</option><option selected>PM</option></select>\r\n                </div>\r\n              </div>\r\n            </div>\r\n\r\n            <div style=\"display: flex; gap: 8px;\">\r\n              <button class=\"vnd-btn vnd-btn-secondary\" style=\"flex: 1;\" onclick=\"VendorController.setRegStep(1)\">← Back</button>\r\n              <button class=\"cta-primary-btn vnd-btn-big\" style=\"flex: 2;\" onclick=\"VendorController.setRegStep(3)\">Next: Media →</button>\r\n            </div>\r\n          </div>\r\n\r\n          <!-- Step 3: Media Upload -->\r\n          <div id=\"v-reg-step-3\" class=\"vnd-step\" style=\"display: none;\">\r\n            <h4 class=\"vnd-step-title\">Step 3 · Add Your Store Banner</h4>\r\n            <p class=\"vnd-muted\">A clean photo catches hungry customers. You can always change it later.</p>\r\n            <div class=\"vnd-uploader\">\r\n              <input type=\"file\" id=\"v-reg-banner-input\" accept=\"image/*\" style=\"display: none;\" />\r\n              <div id=\"v-reg-banner-pick\" class=\"vnd-upload-box\" onclick=\"document.getElementById('v-reg-banner-input').click()\">\r\n                <div class=\"vnd-upload-emoji\">📸</div>\r\n                <div class=\"vnd-upload-title\">Tap to add your store banner</div>\r\n                <div class=\"vnd-upload-hint\">Take or choose a photo</div>\r\n              </div>\r\n              <img id=\"v-reg-banner-preview\" class=\"vnd-upload-preview\" style=\"display: none;\" alt=\"Banner preview\" />\r\n              <button id=\"v-reg-banner-change\" class=\"vnd-btn vnd-btn-secondary vnd-btn-sm\" style=\"display: none; margin-top: 8px;\" onclick=\"document.getElementById('v-reg-banner-input').click()\">Change Photo</button>\r\n            </div>\r\n            <div style=\"display: flex; gap: 8px;\">\r\n              <button class=\"vnd-btn vnd-btn-secondary\" style=\"flex: 1;\" onclick=\"VendorController.setRegStep(2)\">← Back</button>\r\n              <button class=\"cta-primary-btn vnd-btn-big\" style=\"flex: 2;\" onclick=\"VendorController.submitVendorRegistration()\">Submit for Verification ✓</button>\r\n            </div>\r\n          </div>\r\n\r\n          <!-- Step 4: Verification Holding -->\r\n          <div id=\"v-reg-step-4\" class=\"vnd-step vnd-step-center\" style=\"display: none;\">\r\n            <div class=\"vnd-holding-icon\">⏳</div>\r\n            <h3 class=\"vnd-holding-title\">Account Under Verification</h3>\r\n            <p class=\"vnd-holding-text\">Our team is reviewing your details. You will be notified once approved.</p>\r\n            <button class=\"cta-primary-btn vnd-btn-big\" onclick=\"VendorController.closeRegistrationModal()\">Got it, I'll wait</button>\r\n          </div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n\r\n    <!-- Modal 5b: Streamlined Step-by-Step Food Creation Flow (Points 4–26) -->\r\n    <div id=\"vendor-food-flow-modal\" class=\"modal-backdrop\">\r\n      <div class=\"modal-sheet vnd-flow-sheet\" style=\"max-width: 520px;\">\r\n        \r\n        <!-- Flow Modal Header -->\r\n        <div class=\"modal-header vnd-flow-header\">\r\n          <div class=\"vnd-flow-header-left\">\r\n            <button id=\"vnd-flow-back-btn\" class=\"vnd-icon-btn\" onclick=\"VendorController.flowBack()\" style=\"display: none;\" title=\"Go back\">\r\n              ←\r\n            </button>\r\n            <div>\r\n              <div class=\"modal-title\" id=\"vnd-flow-modal-title\">Add Food</div>\r\n              <div style=\"display: flex; align-items: center; gap: 8px; flex-wrap: wrap;\">\r\n                <div class=\"vnd-flow-step-tag\" id=\"vnd-flow-step-tag\">Step 1 of 6 · Food Details</div>\r\n                <div id=\"vnd-draft-status-pill\" style=\"display: none; align-items: center; gap: 4px; font-size: 0.72rem; color: #0C513F; background: #E8F6F0; padding: 2px 8px; border-radius: 999px; font-weight: 700;\">\r\n                  <span style=\"font-size: 0.65rem;\">🟢</span> Draft auto-saved\r\n                </div>\r\n              </div>\r\n            </div>\r\n          </div>\r\n          <button class=\"modal-close-btn\" onclick=\"VendorController.closeFoodFlow()\">✕</button>\r\n        </div>\r\n\r\n        <!-- Step Progress Indicator -->\r\n        <div class=\"vnd-flow-progress-bar\">\r\n          <div class=\"vnd-flow-progress-fill\" id=\"vnd-flow-progress-fill\" style=\"width: 16.66%;\"></div>\r\n        </div>\r\n\r\n        <div class=\"modal-body vnd-flow-body\">\r\n\r\n          <!-- ════ STEP 1: What are you selling? (Points 4 & 5) ════ -->\r\n          <div id=\"vnd-step-pane-1\" class=\"vnd-step-pane active\">\r\n            <div class=\"vnd-step-question\">What are you selling?</div>\r\n            \r\n            <div class=\"checkout-input-group\">\r\n              <label class=\"checkout-label\">Food name</label>\r\n              <input type=\"text\" id=\"vnd-flow-name\" class=\"checkout-input vnd-flow-input\" placeholder=\"e.g. Jollof Rice\" autofocus />\r\n            </div>\r\n\r\n            <div class=\"checkout-input-group\">\r\n              <label class=\"checkout-label\">Category</label>\r\n              <select id=\"vnd-flow-category\" class=\"checkout-input vnd-flow-select\" onchange=\"VendorController.onFlowCategoryChange()\">\r\n                <option value=\"rice\">Rice</option>\r\n                <option value=\"soups\">Soups</option>\r\n                <option value=\"swallows\">Swallow</option>\r\n                <option value=\"drinks\">Drinks</option>\r\n                <option value=\"snacks\">Snacks &amp; Small Chops</option>\r\n                <option value=\"grills\">Grills &amp; BBQ</option>\r\n                <option value=\"shawarma\">Shawarma</option>\r\n                <option value=\"others\">Others</option>\r\n              </select>\r\n              <p class=\"vnd-step-helper\" id=\"vnd-flow-category-hint\" style=\"margin-top: 6px;\"></p>\r\n            </div>\r\n\r\n            <div class=\"checkout-input-group\">\r\n              <label class=\"checkout-label\">Add a photo</label>\r\n              <div class=\"vnd-photo-dropzone\" id=\"vnd-photo-dropzone\" onclick=\"document.getElementById('vnd-flow-file-input').click()\">\r\n                <input type=\"file\" id=\"vnd-flow-file-input\" accept=\"image/*,.png,.jpg,.jpeg,.webp,.avif,.heic,.heif,.bmp,.gif,.svg,.jfif,.tif,.tiff\" style=\"display: none;\" />\r\n                <div id=\"vnd-photo-empty-state\">\r\n                  <div class=\"vnd-photo-icon\">📷</div>\r\n                  <div class=\"vnd-photo-title\">Add food photo</div>\r\n                  <div class=\"vnd-photo-sub\">Choose any picture format (PNG, JPG, WebP, GIF, SVG, etc.)</div>\r\n                </div>\r\n                <div id=\"vnd-photo-preview-wrap\" style=\"display: none;\">\r\n                  <img id=\"vnd-flow-photo-preview\" src=\"\" alt=\"Food Preview\" />\r\n                  <button type=\"button\" class=\"vnd-photo-change-btn\" onclick=\"event.stopPropagation(); document.getElementById('vnd-flow-file-input').click()\">Change Photo</button>\r\n                </div>\r\n              </div>\r\n              <div id=\"vnd-photo-error-message\" style=\"display: none; color: #DC2626; background: #FEE2E2; border: 1px solid #FCA5A5; padding: 8px 12px; border-radius: 10px; font-size: 0.8rem; font-weight: 600; margin-top: 8px; text-align: center;\"></div>\r\n            </div>\r\n\r\n            <div class=\"checkout-input-group\">\r\n              <div style=\"display: flex; justify-content: space-between; align-items: baseline;\">\r\n                <label class=\"checkout-label\">Tell customers about it</label>\r\n                <span class=\"vnd-optional-pill\">Optional</span>\r\n              </div>\r\n              <textarea id=\"vnd-flow-desc\" class=\"checkout-textarea vnd-flow-textarea\" rows=\"2\" placeholder=\"e.g. Delicious Nigerian smoky jollof rice served with spiced tomato stew...\"></textarea>\r\n            </div>\r\n\r\n            <div class=\"vnd-flow-actions\">\r\n              <button class=\"cta-primary-btn vnd-btn-big vnd-flow-btn-next\" onclick=\"VendorController.validateStep1AndNext()\">\r\n                Continue to Pricing →\r\n              </button>\r\n            </div>\r\n          </div>\r\n\r\n          <!-- ════ STEP 2: How do you sell this food? (Points 6–9) ════ -->\r\n          <div id=\"vnd-step-pane-2\" class=\"vnd-step-pane\" style=\"display: none;\">\r\n            <div class=\"vnd-step-question\" id=\"vnd-step2-question\">How do you sell this food?</div>\r\n            <p class=\"vnd-step-helper\" id=\"vnd-step2-helper\">Tap the option that best matches how you serve this dish.</p>\r\n\r\n            <!-- By-piece pricing (drinks, snacks, grills, shawarma, others) -->\r\n            <div id=\"vnd-piece-price-group\" class=\"checkout-input-group\" style=\"display: none; margin-top: 18px;\">\r\n              <label class=\"checkout-label\" id=\"vnd-piece-price-label\">Price per piece</label>\r\n              <div class=\"vnd-currency-input-wrap\">\r\n                <span class=\"vnd-currency-prefix\">₦</span>\r\n                <input type=\"number\" id=\"vnd-flow-price-piece\" class=\"checkout-input vnd-currency-input\" placeholder=\"e.g. 500\" min=\"0\" step=\"50\" />\r\n              </div>\r\n              <p class=\"vnd-step-helper\" id=\"vnd-piece-price-hint\" style=\"margin-top: 6px;\">This is the price used when no size is chosen.</p>\r\n            </div>\r\n\r\n            <!-- ── Sizes question: only shown for by-piece items ── -->\r\n            <div id=\"vnd-sizes-question-wrap\" style=\"display: none; margin-top: 22px;\">\r\n              <div class=\"vnd-extras-sec-title\">Does this come in different sizes?</div>\r\n              <p class=\"vnd-step-helper\">For example Small, Medium and Large, or Regular and Large.</p>\r\n\r\n              <div class=\"vnd-extras-choice-grid\" style=\"margin-top: 12px;\">\r\n                <div class=\"vnd-choice-card\" id=\"vnd-choice-sizes-yes\" onclick=\"VendorController.setHasSizes(true)\">\r\n                  <div class=\"vnd-choice-emoji\">📏</div>\r\n                  <div class=\"vnd-choice-title\">YES</div>\r\n                  <div class=\"vnd-choice-sub\">It has sizes</div>\r\n                </div>\r\n\r\n                <div class=\"vnd-choice-card selected\" id=\"vnd-choice-sizes-no\" onclick=\"VendorController.setHasSizes(false)\">\r\n                  <div class=\"vnd-choice-emoji\">🚫</div>\r\n                  <div class=\"vnd-choice-title\">NO</div>\r\n                  <div class=\"vnd-choice-sub\">One price only</div>\r\n                </div>\r\n              </div>\r\n            </div>\r\n\r\n            <!-- ── Size / price builder ── -->\r\n            <div id=\"vnd-sizes-builder-wrap\" style=\"display: none; margin-top: 20px;\">\r\n              <div class=\"vnd-extras-section-box\">\r\n                <div class=\"vnd-extras-sec-header\">\r\n                  <div>\r\n                    <div class=\"vnd-extras-sec-title\">Sizes and prices</div>\r\n                    <div class=\"vnd-extras-sec-sub\">Customers must pick one of these before ordering.</div>\r\n                  </div>\r\n                  <button type=\"button\" class=\"vnd-btn-add-extra-pill\" onclick=\"VendorController.addSize()\">\r\n                    ＋ Add size\r\n                  </button>\r\n                </div>\r\n\r\n                <div class=\"vnd-size-presets\" id=\"vnd-size-presets\"></div>\r\n                <div id=\"vnd-sizes-list\" class=\"vnd-extras-items-list\"></div>\r\n              </div>\r\n            </div>\r\n\r\n            <!-- Portion pricing (rice, soups, swallow) -->\r\n            <div id=\"vnd-portion-price-wrap\" style=\"display: none;\">\r\n              <div class=\"vnd-price-type-grid\">\r\n                <div class=\"vnd-price-type-card\" id=\"vnd-pt-scoop\" onclick=\"VendorController.setPriceType('SCOOP')\">\r\n                  <div class=\"vnd-pt-icon\">🥄</div>\r\n                  <div class=\"vnd-pt-title\">Per Scoop</div>\r\n                  <div class=\"vnd-pt-sub\">Price each scoop</div>\r\n                </div>\r\n\r\n                <div class=\"vnd-price-type-card selected\" id=\"vnd-pt-plate\" onclick=\"VendorController.setPriceType('PLATE')\">\r\n                  <div class=\"vnd-pt-icon\">🍽️</div>\r\n                  <div class=\"vnd-pt-title\">Per Plate</div>\r\n                  <div class=\"vnd-pt-sub\">Price each plate</div>\r\n                </div>\r\n\r\n                <div class=\"vnd-price-type-card\" id=\"vnd-pt-both\" onclick=\"VendorController.setPriceType('BOTH')\">\r\n                  <div class=\"vnd-pt-icon\">➕</div>\r\n                  <div class=\"vnd-pt-title\">Both</div>\r\n                  <div class=\"vnd-pt-sub\">Scoop + Plate</div>\r\n                </div>\r\n              </div>\r\n\r\n              <!-- Price input fields based on selection -->\r\n              <div id=\"vnd-scoop-price-group\" class=\"checkout-input-group\" style=\"display: none; margin-top: 18px;\">\r\n                <label class=\"checkout-label\">Price per scoop</label>\r\n                <div class=\"vnd-currency-input-wrap\">\r\n                  <span class=\"vnd-currency-prefix\">₦</span>\r\n                  <input type=\"number\" id=\"vnd-flow-price-scoop\" class=\"checkout-input vnd-currency-input\" placeholder=\"e.g. 500\" min=\"0\" step=\"50\" />\r\n                </div>\r\n              </div>\r\n\r\n              <div id=\"vnd-plate-price-group\" class=\"checkout-input-group\" style=\"margin-top: 18px;\">\r\n                <label class=\"checkout-label\">Price per plate</label>\r\n                <div class=\"vnd-currency-input-wrap\">\r\n                  <span class=\"vnd-currency-prefix\">₦</span>\r\n                  <input type=\"number\" id=\"vnd-flow-price-plate\" class=\"checkout-input vnd-currency-input\" placeholder=\"e.g. 2000\" min=\"0\" step=\"100\" />\r\n                </div>\r\n              </div>\r\n            </div>\r\n\r\n            <div class=\"vnd-flow-actions-dual\">\r\n              <button class=\"vnd-btn vnd-btn-secondary vnd-btn-big\" onclick=\"VendorController.goToStep(1)\">← Back</button>\r\n              <button class=\"cta-primary-btn vnd-btn-big vnd-flow-btn-next\" onclick=\"VendorController.validateStep2AndNext()\">Continue →</button>\r\n            </div>\r\n          </div>\r\n\r\n          <!-- ════ STEP 3: Extras (Points 11–18) ════ -->\r\n          <div id=\"vnd-step-pane-3\" class=\"vnd-step-pane\" style=\"display: none;\">\r\n            <div class=\"vnd-step-question\">Does this food have extras?</div>\r\n            <p class=\"vnd-step-helper\">Proteins, drinks, plantain, or sides customers can add.</p>\r\n\r\n            <div class=\"vnd-extras-choice-grid\">\r\n              <div class=\"vnd-choice-card\" id=\"vnd-choice-extras-yes\" onclick=\"VendorController.setHasExtras(true)\">\r\n                <div class=\"vnd-choice-emoji\">🍗</div>\r\n                <div class=\"vnd-choice-title\">YES</div>\r\n                <div class=\"vnd-choice-sub\">Add extras</div>\r\n              </div>\r\n\r\n              <div class=\"vnd-choice-card selected\" id=\"vnd-choice-extras-no\" onclick=\"VendorController.setHasExtras(false)\">\r\n                <div class=\"vnd-choice-emoji\">🚫</div>\r\n                <div class=\"vnd-choice-title\">NO</div>\r\n                <div class=\"vnd-choice-sub\">No extras</div>\r\n              </div>\r\n            </div>\r\n\r\n            <!-- Extras builder sections (revealed when YES is picked) -->\r\n            <div id=\"vnd-extras-builder-wrap\" style=\"display: none; margin-top: 20px;\">\r\n              \r\n              <!-- Compulsory extras section -->\r\n              <div class=\"vnd-extras-section-box\">\r\n                <div class=\"vnd-extras-sec-header\">\r\n                  <div>\r\n                    <div class=\"vnd-extras-sec-title\">Compulsory extras</div>\r\n                    <div class=\"vnd-extras-sec-sub\">The customer must choose these before ordering.</div>\r\n                  </div>\r\n                  <button type=\"button\" class=\"vnd-btn-add-extra-pill\" onclick=\"VendorController.showAddExtraForm('REQUIRED')\">\r\n                    ＋ Add compulsory extra\r\n                  </button>\r\n                </div>\r\n\r\n                <div id=\"vnd-compulsory-extras-list\" class=\"vnd-extras-items-list\">\r\n                  <!-- Injected by vendor.js -->\r\n                </div>\r\n              </div>\r\n\r\n              <!-- Optional extras section -->\r\n              <div class=\"vnd-extras-section-box\" style=\"margin-top: 14px;\">\r\n                <div class=\"vnd-extras-sec-header\">\r\n                  <div>\r\n                    <div class=\"vnd-extras-sec-title\">Optional extras</div>\r\n                    <div class=\"vnd-extras-sec-sub\">Customers can add these if they want.</div>\r\n                  </div>\r\n                  <button type=\"button\" class=\"vnd-btn-add-extra-pill\" onclick=\"VendorController.showAddExtraForm('OPTIONAL')\">\r\n                    ＋ Add optional extra\r\n                  </button>\r\n                </div>\r\n\r\n                <div id=\"vnd-optional-extras-list\" class=\"vnd-extras-items-list\">\r\n                  <!-- Injected by vendor.js -->\r\n                </div>\r\n              </div>\r\n\r\n              <!-- Quick Mini Form for adding an extra -->\r\n              <div id=\"vnd-quick-extra-modal\" class=\"vnd-quick-extra-box\" style=\"display: none;\">\r\n                <div class=\"vnd-quick-extra-head\">\r\n                  <span id=\"vnd-quick-extra-type-label\">Add Extra</span>\r\n                  <button type=\"button\" class=\"vnd-icon-btn-sm\" onclick=\"VendorController.hideAddExtraForm()\">✕</button>\r\n                </div>\r\n                <div class=\"vnd-quick-extra-inputs\">\r\n                  <input type=\"text\" id=\"vnd-quick-extra-name\" class=\"checkout-input vnd-flow-input\" placeholder=\"e.g. Chicken or Extra Egg\" />\r\n                  <div class=\"vnd-currency-input-wrap\">\r\n                    <span class=\"vnd-currency-prefix\">₦</span>\r\n                    <input type=\"number\" id=\"vnd-quick-extra-price\" class=\"checkout-input vnd-currency-input\" placeholder=\"1000\" min=\"0\" step=\"50\" />\r\n                  </div>\r\n                </div>\r\n                <div class=\"vnd-quick-extra-btns\">\r\n                  <button type=\"button\" class=\"vnd-btn vnd-btn-secondary vnd-btn-sm\" onclick=\"VendorController.hideAddExtraForm()\">Cancel</button>\r\n                  <button type=\"button\" class=\"cta-primary-btn vnd-btn-sm\" onclick=\"VendorController.saveQuickExtra()\">Save Extra</button>\r\n                </div>\r\n              </div>\r\n            </div>\r\n\r\n            <div class=\"vnd-flow-actions-dual\">\r\n              <button class=\"vnd-btn vnd-btn-secondary vnd-btn-big\" onclick=\"VendorController.goToStep(2)\">← Back</button>\r\n              <button class=\"cta-primary-btn vnd-btn-big vnd-flow-btn-next\" onclick=\"VendorController.goToStep(4)\">Continue →</button>\r\n            </div>\r\n          </div>\r\n\r\n          <!-- ════ STEP 4: Availability (Point 19) ════ -->\r\n          <div id=\"vnd-step-pane-4\" class=\"vnd-step-pane\" style=\"display: none;\">\r\n            <div class=\"vnd-step-question\">Is this food available now?</div>\r\n            <p class=\"vnd-step-helper\">Customers will immediately see this status when browsing your store.</p>\r\n\r\n            <div class=\"vnd-avail-card\" id=\"vnd-avail-card\">\r\n              <div class=\"vnd-avail-info\">\r\n                <div class=\"vnd-avail-badge\" id=\"vnd-avail-status-badge\">\r\n                  <span id=\"vnd-avail-dot\">🟢</span> <span id=\"vnd-avail-text\">Available</span>\r\n                </div>\r\n                <div class=\"vnd-avail-sub\" id=\"vnd-avail-subtext\">Customers can order this food right now.</div>\r\n              </div>\r\n\r\n              <div id=\"vnd-flow-avail-toggle\" class=\"toggle-switch on\" onclick=\"VendorController.toggleFlowAvailability()\">\r\n                <div class=\"toggle-knob\"></div>\r\n              </div>\r\n            </div>\r\n\r\n            <div class=\"vnd-flow-actions-dual\">\r\n              <button class=\"vnd-btn vnd-btn-secondary vnd-btn-big\" onclick=\"VendorController.goToStep(3)\">← Back</button>\r\n              <button class=\"cta-primary-btn vnd-btn-big vnd-flow-btn-next\" onclick=\"VendorController.goToStep(5)\">Continue →</button>\r\n            </div>\r\n          </div>\r\n\r\n          <!-- ════ STEP 5: Pre-order (Points 20–22) ════ -->\r\n          <div id=\"vnd-step-pane-5\" class=\"vnd-step-pane\" style=\"display: none;\">\r\n            <div class=\"vnd-step-question\">Pre-order</div>\r\n            <p class=\"vnd-step-helper\">Let customers order this food before it's ready.</p>\r\n\r\n            <div class=\"vnd-avail-card\" style=\"margin-bottom: 16px;\">\r\n              <div class=\"vnd-avail-info\">\r\n                <div class=\"vnd-avail-title\">Enable pre-order</div>\r\n                <div class=\"vnd-avail-sub\">Customers can reserve this item for a future date/time.</div>\r\n              </div>\r\n\r\n              <div id=\"vnd-flow-preorder-toggle\" class=\"toggle-switch\" onclick=\"VendorController.toggleFlowPreorder()\">\r\n                <div class=\"toggle-knob\"></div>\r\n              </div>\r\n            </div>\r\n\r\n            <!-- Preorder date & time picker (revealed when enabled) -->\r\n            <div id=\"vnd-preorder-fields-wrap\" style=\"display: none;\" class=\"vnd-preorder-box\">\r\n              <div class=\"vnd-preorder-heading\">When will this food be available?</div>\r\n              \r\n              <div class=\"checkout-input-group\">\r\n                <label class=\"checkout-label\">Available Date</label>\r\n                <input type=\"date\" id=\"vnd-flow-preorder-date\" class=\"checkout-input vnd-flow-input\" />\r\n              </div>\r\n\r\n              <div class=\"checkout-input-group\">\r\n                <label class=\"checkout-label\">Available from (Time)</label>\r\n                <input type=\"time\" id=\"vnd-flow-preorder-time\" class=\"checkout-input vnd-flow-input\" value=\"12:00\" />\r\n              </div>\r\n            </div>\r\n\r\n            <div class=\"vnd-flow-actions-dual\">\r\n              <button class=\"vnd-btn vnd-btn-secondary vnd-btn-big\" onclick=\"VendorController.goToStep(4)\">← Back</button>\r\n              <button class=\"cta-primary-btn vnd-btn-big vnd-flow-btn-next\" onclick=\"VendorController.goToReviewStep()\">Review Food →</button>\r\n            </div>\r\n          </div>\r\n\r\n          <!-- ════ STEP 6: Final Review Screen (Point 24) ════ -->\r\n          <div id=\"vnd-step-pane-6\" class=\"vnd-step-pane\" style=\"display: none;\">\r\n            <div class=\"vnd-step-question\">Looks good?</div>\r\n            <p class=\"vnd-step-helper\">Check the details below before publishing to your Chow45 menu.</p>\r\n\r\n            <!-- Preview Card -->\r\n            <div class=\"vnd-review-card\">\r\n              <img id=\"vnd-review-photo\" class=\"vnd-review-img\" src=\"\" alt=\"Food Preview\" />\r\n              \r\n              <div class=\"vnd-review-body\">\r\n                <div class=\"vnd-review-title\" id=\"vnd-review-name\">Jollof Rice</div>\r\n                <div class=\"vnd-review-price\" id=\"vnd-review-price\">₦2,000 / plate</div>\r\n\r\n                <div class=\"vnd-review-extras-box\" id=\"vnd-review-sizes-wrap\" style=\"display: none;\">\r\n                  <span class=\"vnd-review-lbl\">Sizes:</span>\r\n                  <span class=\"vnd-review-val\" id=\"vnd-review-sizes-val\">Small ₦500, Large ₦900</span>\r\n                </div>\r\n\r\n                <div class=\"vnd-review-extras-box\" id=\"vnd-review-compulsory-wrap\" style=\"display: none;\">\r\n                  <span class=\"vnd-review-lbl\">Compulsory:</span>\r\n                  <span class=\"vnd-review-val\" id=\"vnd-review-compulsory-val\">Chicken +₦1,000</span>\r\n                </div>\r\n\r\n                <div class=\"vnd-review-extras-box\" id=\"vnd-review-optional-wrap\" style=\"display: none;\">\r\n                  <span class=\"vnd-review-lbl\">Optional:</span>\r\n                  <span class=\"vnd-review-val\" id=\"vnd-review-optional-val\">Egg +₦500, Plantain +₦700</span>\r\n                </div>\r\n\r\n                <div class=\"vnd-review-status-row\">\r\n                  <span class=\"vnd-badge-status\" id=\"vnd-review-status-badge\">🟢 Available</span>\r\n                </div>\r\n              </div>\r\n            </div>\r\n\r\n            <!-- Prominent Publish Error Container -->\r\n            <div id=\"vnd-publish-error\" style=\"display: none; color: #DC2626; background: #FEE2E2; border: 1px solid #FCA5A5; padding: 12px 16px; border-radius: 12px; margin-bottom: 14px; font-size: 0.88rem; font-weight: 600; text-align: left;\"></div>\r\n\r\n            <div class=\"vnd-flow-actions-dual\">\r\n              <button class=\"vnd-btn vnd-btn-secondary vnd-btn-big\" onclick=\"VendorController.goToStep(5)\">← Edit</button>\r\n              <button class=\"cta-primary-btn vnd-btn-big vnd-btn-publish\" id=\"vnd-flow-publish-btn\" onclick=\"VendorController.publishFoodDraft()\">\r\n                Publish Food ✓\r\n              </button>\r\n            </div>\r\n          </div>\r\n\r\n          <!-- ════ STEP 7: Success Screen (Points 25 & 26) ════ -->\r\n          <div id=\"vnd-step-pane-7\" class=\"vnd-step-pane vnd-step-center\" style=\"display: none;\">\r\n            <div class=\"vnd-success-icon\">🎉</div>\r\n            <h2 class=\"vnd-success-title\">Food added!</h2>\r\n            <p class=\"vnd-success-text\" id=\"vnd-success-message\">Your food is now live on your Chow45 menu.</p>\r\n\r\n            <div class=\"vnd-success-actions\">\r\n              <button class=\"cta-primary-btn vnd-btn-big\" onclick=\"VendorController.openAddFoodFlow()\">\r\n                ＋ Add another food\r\n              </button>\r\n              <button class=\"vnd-btn vnd-btn-secondary vnd-btn-big\" onclick=\"VendorController.closeFoodFlow()\">\r\n                View my food\r\n              </button>\r\n            </div>\r\n          </div>\r\n\r\n        </div>\r\n      </div>\r\n    </div>\r\n\r\n\r\n    <!-- Modal 6: Customer Order History (Point 24) -->\r\n    <div id=\"order-history-modal\" class=\"modal-backdrop\">\r\n      <div class=\"modal-sheet\" style=\"max-width: 520px;\">\r\n        <div class=\"modal-header\">\r\n          <div class=\"modal-title\">My Orders</div>\r\n          <button class=\"modal-close-btn\" onclick=\"document.getElementById('order-history-modal').classList.remove('open')\">✕</button>\r\n        </div>\r\n        <div class=\"modal-body\">\r\n          <div id=\"order-history-list\">\r\n            <!-- Injected by customer.js -->\r\n          </div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n\r\n    <!-- Modal 7: Post-Delivery Order Rating (Point 65) -->\r\n    <div id=\"review-modal\" class=\"modal-backdrop\">\r\n      <div class=\"modal-sheet\" style=\"max-width: 440px;\">\r\n        <div class=\"modal-header\">\r\n          <div class=\"modal-title\">How was your order?</div>\r\n          <button class=\"modal-close-btn\" onclick=\"document.getElementById('review-modal').classList.remove('open')\">✕</button>\r\n        </div>\r\n        <div class=\"modal-body\" style=\"text-align: center;\">\r\n          <p style=\"font-size: 0.85rem; color: var(--c-text-secondary); margin-bottom: 12px;\">Order #<span id=\"review-order-id\"></span></p>\r\n          <div style=\"font-size: 2rem; margin-bottom: 12px; cursor: pointer;\">\r\n            ⭐⭐⭐⭐⭐\r\n          </div>\r\n          <div class=\"checkout-input-group\">\r\n            <textarea id=\"review-comment-input\" class=\"checkout-textarea\" rows=\"3\" placeholder=\"Leave a short review for the restaurant and rider...\"></textarea>\r\n          </div>\r\n          <button class=\"cta-primary-btn\" onclick=\"CustomerController.submitReview()\">\r\n            Submit Rating\r\n          </button>\r\n        </div>\r\n      </div>\r\n    </div>\r\n\r\n    <!-- Modal 8: Rider Delivery Confirmation PIN Input -->\r\n    <div id=\"rider-pin-modal\" class=\"modal-backdrop\">\r\n      <div class=\"modal-sheet\" style=\"max-width: 420px; text-align: center;\">\r\n        <div class=\"modal-header\">\r\n          <div class=\"modal-title\">Complete Delivery</div>\r\n          <button class=\"modal-close-btn\" onclick=\"RiderController.closePinModal()\">✕</button>\r\n        </div>\r\n        <div class=\"modal-body\" style=\"padding: 24px 20px 20px;\">\r\n          <div style=\"font-size: 2.5rem; line-height: 1; margin-bottom: 10px;\">🔐</div>\r\n          <h3 style=\"font-family: var(--font-display); font-size: 1.25rem; font-weight: 800; margin: 0 0 6px;\">Customer Delivery PIN</h3>\r\n          <p style=\"font-size: 0.85rem; color: var(--c-text-secondary); margin: 0 0 20px;\">\r\n            Ask the customer for their 4-digit confirmation PIN to confirm meal handover.\r\n          </p>\r\n\r\n          <div style=\"display: flex; justify-content: center; margin-bottom: 12px;\">\r\n            <input type=\"text\" id=\"rider-modal-pin\" maxlength=\"4\" inputmode=\"numeric\" pattern=\"[0-9]*\" placeholder=\"••••\"\r\n              style=\"font-family: monospace; font-size: 2.2rem; font-weight: 800; letter-spacing: 12px; text-align: center; width: 220px; padding: 12px 14px; border-radius: var(--radius-lg); border: 2px solid var(--c-primary); background: var(--c-bg-surface); color: var(--c-text-primary); outline: none;\" />\r\n          </div>\r\n\r\n          <div id=\"rider-pin-modal-error\" style=\"display: none; color: #DC2626; font-size: 0.82rem; font-weight: 700; margin-bottom: 16px; background: #FEF2F2; padding: 8px 12px; border-radius: var(--radius-md);\"></div>\r\n\r\n          <div style=\"display: flex; gap: 10px; margin-top: 8px;\">\r\n            <button type=\"button\" class=\"vnd-btn vnd-btn-secondary\" style=\"flex: 1; padding: 12px;\" onclick=\"RiderController.closePinModal()\">Cancel</button>\r\n            <button type=\"button\" class=\"cta-primary-btn\" style=\"flex: 2; padding: 14px; font-weight: 800; background: #10B981;\" onclick=\"RiderController.submitPinAndComplete()\">\r\n              Confirm &amp; Complete ✓\r\n            </button>\r\n          </div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n\r\n    <!-- Modal 9: Authentication (Redesigned Flow) -->\r\n    <!-- ═══════════════════════════════════════════════════════════\r\n         VENDOR ONBOARDING GATE (first visit to /vendor)\r\n         Welcome → Service area → Sign in / create account\r\n         ═══════════════════════════════════════════════════════════ -->\r\n    <div id=\"vendor-onboarding\" class=\"vnd-onb\" style=\"display: none;\" role=\"dialog\" aria-modal=\"true\" aria-labelledby=\"vnd-onb-title\">\r\n      <div class=\"vnd-onb-card\">\r\n        <div class=\"vnd-onb-progress\" aria-hidden=\"true\">\r\n          <span class=\"vnd-onb-dot active\" data-onb-step-dot=\"0\"></span>\r\n          <span class=\"vnd-onb-dot\" data-onb-step-dot=\"1\"></span>\r\n          <span class=\"vnd-onb-dot\" data-onb-step-dot=\"2\"></span>\r\n        </div>\r\n\r\n        <div class=\"vnd-onb-step active\" data-onb-step=\"0\">\r\n          <div class=\"vnd-onb-icon\" aria-hidden=\"true\">🍽️</div>\r\n          <h1 class=\"vnd-onb-title\" id=\"vnd-onb-title\">Welcome to Chow45 Vendors</h1>\r\n          <p class=\"vnd-onb-text\">Sell your food to students around campus. Setting up takes three quick steps.</p>\r\n          <ul class=\"vnd-onb-perks\">\r\n            <li><span aria-hidden=\"true\">🎓</span> Reach hungry students near you</li>\r\n            <li><span aria-hidden=\"true\">🍛</span> Set your own prices and menu</li>\r\n            <li><span aria-hidden=\"true\">💸</span> Get paid straight to your account</li>\r\n          </ul>\r\n          <button type=\"button\" class=\"vnd-onb-btn\" onclick=\"VendorOnboarding.next(0)\">\r\n            <span>Get Started</span>\r\n          </button>\r\n        </div>\r\n\r\n        <div class=\"vnd-onb-step\" data-onb-step=\"1\">\r\n          <div class=\"vnd-onb-icon\" aria-hidden=\"true\">📍</div>\r\n          <h1 class=\"vnd-onb-title\">Where do you sell?</h1>\r\n          <p class=\"vnd-onb-text\">Pick the area your store is in so we can show you to the right customers.</p>\r\n\r\n          <div class=\"checkout-input-group\">\r\n            <label class=\"checkout-label\" for=\"vnd-onb-zone\">Your area</label>\r\n            <div class=\"auth-input-wrap\">\r\n              <span class=\"auth-input-icon\" aria-hidden=\"true\">📍</span>\r\n              <select id=\"vnd-onb-zone\" class=\"checkout-input auth-input\" onchange=\"VendorOnboarding.chooseZone();\">\r\n                <option value=\"\">Select your area...</option>\r\n                <option value=\"ibogun-campus\">Ibogun</option>\r\n                <option value=\"sagamu-campus\">Sagammu</option>\r\n              </select>\r\n            </div>\r\n            <p class=\"vnd-onb-hint error\" id=\"vnd-onb-zone-hint\" style=\"display: none;\"></p>\r\n          </div>\r\n\r\n          <div class=\"vnd-onb-actions\">\r\n            <button type=\"button\" class=\"vnd-onb-btn ghost\" onclick=\"VendorOnboarding.back()\">\r\n              <span>Back</span>\r\n            </button>\r\n            <button type=\"button\" class=\"vnd-onb-btn\" onclick=\"VendorOnboarding.continueFromArea()\">\r\n              <span>Continue</span>\r\n            </button>\r\n          </div>\r\n        </div>\r\n\r\n        <div class=\"vnd-onb-step\" data-onb-step=\"2\">\r\n          <div class=\"vnd-onb-icon\" aria-hidden=\"true\">🔐</div>\r\n          <h1 class=\"vnd-onb-title\">Sign in to your account</h1>\r\n          <p class=\"vnd-onb-text\">Enter your email to continue. If you are new here, we will set up your vendor account for you.</p>\r\n          <span class=\"vnd-onb-chip\" id=\"vnd-onb-zone-chip\" style=\"display: none;\"></span>\r\n\r\n          <button type=\"button\" class=\"vnd-onb-btn\" id=\"vnd-onb-auth-btn\" onclick=\"VendorOnboarding.openAuth()\">\r\n            <span>Continue with Email</span>\r\n          </button>\r\n\r\n          <div class=\"vnd-onb-actions\">\r\n            <button type=\"button\" class=\"vnd-onb-btn ghost\" onclick=\"VendorOnboarding.back()\">\r\n              <span>Change area</span>\r\n            </button>\r\n          </div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n\r\n    <div id=\"auth-modal\" class=\"modal-backdrop\">\r\n      <div class=\"modal-sheet auth-modal-sheet\">\r\n        <div class=\"modal-header auth-modal-header\">\r\n          <div class=\"auth-header-left\">\r\n            <button type=\"button\" id=\"auth-header-back-btn\" class=\"auth-back-nav-btn\" style=\"display: none;\" onclick=\"Chow45Auth.showStep1()\">\r\n              ← Back\r\n            </button>\r\n            <div class=\"auth-brand-row\">\r\n              <span class=\"auth-logo-badge\">CHOW45</span>\r\n              <span id=\"auth-modal-header-tag\" class=\"auth-modal-tag\">Sign In / Join</span>\r\n            </div>\r\n          </div>\r\n          <button class=\"modal-close-btn\" onclick=\"Chow45Auth.close()\">✕</button>\r\n        </div>\r\n\r\n        <div class=\"modal-body auth-modal-body\">\r\n          <!-- ─── STEP 1: INITIAL POPUP (Single Email Input + Continue + Vendor Prompt) ─── -->\r\n          <div id=\"auth-step-1\" class=\"auth-flow-step active\">\r\n            <div class=\"auth-panel-intro\">\r\n              <h3 class=\"auth-heading\">Welcome to Chow45</h3>\r\n              <p class=\"auth-subheading\">Enter your email address to continue.</p>\r\n            </div>\r\n\r\n            <div id=\"auth-step1-alert\" class=\"auth-alert error\" style=\"display: none;\"></div>\r\n\r\n            <form onsubmit=\"event.preventDefault(); Chow45Auth.handleStep1Continue();\">\r\n              <div class=\"checkout-input-group\" style=\"margin-top: 14px;\">\r\n                <label class=\"checkout-label\" for=\"auth-step1-email\">Email Address</label>\r\n                <div class=\"auth-input-wrap\">\r\n                  <span class=\"auth-input-icon\">✉️</span>\r\n                  <input type=\"email\" id=\"auth-step1-email\" class=\"checkout-input auth-input\" placeholder=\"e.g. name@student.oou.edu.ng\" required autofocus autocomplete=\"email\" onblur=\"Chow45Auth.checkStep1EmailInput(true)\" />\r\n                </div>\r\n              </div>\r\n\r\n              <button type=\"submit\" id=\"auth-step1-btn\" class=\"cta-primary-btn auth-submit-btn\" style=\"margin-top: 16px;\">\r\n                <span>Continue →</span>\r\n              </button>\r\n            </form>\r\n\r\n            <div class=\"auth-vendor-callout\">\r\n              <span>Are you a vendor?</span>\r\n              <button type=\"button\" class=\"auth-vendor-link\" onclick=\"Chow45Auth.showVendorStep()\">Create an account here</button>\r\n            </div>\r\n          </div>\r\n\r\n          <!-- ─── STEP 1B: PASSWORD (existing accounts only) ─── -->\r\n          <div id=\"auth-step-password\" class=\"auth-flow-step\" style=\"display: none;\">\r\n            <div class=\"auth-panel-intro\">\r\n              <h3 class=\"auth-heading\" id=\"auth-password-heading\">Welcome back</h3>\r\n              <p class=\"auth-subheading\" id=\"auth-password-subheading\">Enter your password to sign in.</p>\r\n            </div>\r\n\r\n            <div id=\"auth-password-alert\" class=\"auth-alert error\" style=\"display: none;\"></div>\r\n\r\n            <!-- Email Banner with Change button -->\r\n            <div style=\"display: flex; align-items: center; justify-content: space-between; background: #FAF6EB; padding: 10px 14px; border-radius: 12px; margin-top: 12px; margin-bottom: 14px; border: 1px solid rgba(12,81,63,0.15);\">\r\n              <div style=\"display: flex; align-items: center; gap: 8px; overflow: hidden;\">\r\n                <span style=\"font-size: 1rem;\">✉️</span>\r\n                <div style=\"overflow: hidden;\">\r\n                  <span style=\"font-size: 0.7rem; color: #6E6D66; display: block; text-transform: uppercase; font-weight: 700; letter-spacing: 0.05em;\">Signing in as</span>\r\n                  <strong id=\"auth-password-email-display\" style=\"font-size: 0.88rem; color: #111111; display: block; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;\"></strong>\r\n                </div>\r\n              </div>\r\n              <button type=\"button\" onclick=\"Chow45Auth.showStep1()\" style=\"background: none; border: none; font-size: 0.78rem; font-weight: 700; color: #0C513F; cursor: pointer; text-decoration: underline; flex-shrink: 0; padding-left: 8px;\">Change</button>\r\n            </div>\r\n\r\n            <form onsubmit=\"event.preventDefault(); Chow45Auth.handlePasswordSubmit();\">\r\n              <input type=\"hidden\" id=\"auth-password-email\" />\r\n\r\n              <div class=\"checkout-input-group\">\r\n                <label class=\"checkout-label\" for=\"auth-password\">Password</label>\r\n                <div class=\"auth-input-wrap\">\r\n                  <span class=\"auth-input-icon\">🔒</span>\r\n                  <input type=\"password\" id=\"auth-password\" class=\"checkout-input auth-input\" placeholder=\"••••••••\" required autocomplete=\"current-password\" />\r\n                  <button type=\"button\" class=\"auth-pw-toggle\" onclick=\"Chow45Auth.togglePasswordVisibility('auth-password', this)\">👁️</button>\r\n                </div>\r\n              </div>\r\n\r\n              <button type=\"submit\" id=\"auth-password-btn\" class=\"cta-primary-btn auth-submit-btn\" style=\"margin-top: 16px;\">\r\n                <span>Sign In →</span>\r\n              </button>\r\n            </form>\r\n\r\n            <div style=\"text-align: center; margin-top: 14px;\">\r\n              <button type=\"button\" onclick=\"Chow45Auth.showStep1()\" style=\"background: none; border: none; font-size: 0.8rem; color: #6E6D66; cursor: pointer; text-decoration: underline;\">\r\n                ← Use a different email address\r\n              </button>\r\n            </div>\r\n          </div>\r\n\r\n          <!-- ─── STEP 2: CUSTOMER PROFILE (Email, Phone, Address) ─── -->\r\n          <div id=\"auth-step-customer\" class=\"auth-flow-step\" style=\"display: none;\">\r\n            <div class=\"auth-panel-intro\">\r\n              <h3 class=\"auth-heading\">Create your account</h3>\r\n              <p class=\"auth-subheading\">Complete your details to start ordering delicious meals.</p>\r\n            </div>\r\n\r\n            <!-- Email banner with Change button -->\r\n            <div style=\"display: flex; align-items: center; justify-content: space-between; background: #FAF6EB; padding: 10px 14px; border-radius: 12px; margin-top: 12px; margin-bottom: 12px; border: 1px solid rgba(12,81,63,0.15);\">\r\n              <div style=\"display: flex; align-items: center; gap: 8px; overflow: hidden;\">\r\n                <span style=\"font-size: 1rem;\">✉️</span>\r\n                <div style=\"overflow: hidden;\">\r\n                  <span style=\"font-size: 0.7rem; color: #6E6D66; display: block; text-transform: uppercase; font-weight: 700; letter-spacing: 0.05em;\">New account for</span>\r\n                  <strong id=\"auth-cust-email-display\" style=\"font-size: 0.88rem; color: #111111; display: block; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;\"></strong>\r\n                </div>\r\n              </div>\r\n              <button type=\"button\" onclick=\"Chow45Auth.showStep1()\" style=\"background: none; border: none; font-size: 0.78rem; font-weight: 700; color: #0C513F; cursor: pointer; text-decoration: underline; flex-shrink: 0; padding-left: 8px;\">Change</button>\r\n            </div>\r\n\r\n            <!-- Account Type Switcher: Customer vs Vendor -->\r\n            <div style=\"display: flex; gap: 8px; margin-bottom: 14px;\">\r\n              <button type=\"button\" style=\"flex: 1; padding: 8px 12px; border-radius: 8px; font-size: 0.8rem; font-weight: 800; background: #0C513F; color: #fff; border: 1px solid #0C513F; cursor: default;\">\r\n                🛍️ Order Food\r\n              </button>\r\n              <button type=\"button\" onclick=\"Chow45Auth.showVendorStep()\" style=\"flex: 1; padding: 8px 12px; border-radius: 8px; font-size: 0.8rem; font-weight: 700; background: #FAF6EB; color: #383834; border: 1px solid #E6DEC8; cursor: pointer;\">\r\n                🍳 Sell Food (Vendor) →\r\n              </button>\r\n            </div>\r\n\r\n            <div id=\"auth-cust-alert\" class=\"auth-alert error\" style=\"display: none;\"></div>\r\n\r\n            <form onsubmit=\"event.preventDefault(); Chow45Auth.handleCustomerSubmit();\">\r\n              <input type=\"hidden\" id=\"auth-cust-email\" />\r\n\r\n              <div class=\"checkout-input-group\">\r\n                <label class=\"checkout-label\" for=\"auth-cust-phone\">Phone Number</label>\r\n                <div class=\"auth-input-wrap\">\r\n                  <span class=\"auth-input-icon\">📱</span>\r\n                    <input type=\"tel\" id=\"auth-cust-phone\" class=\"checkout-input auth-input\" placeholder=\"e.g. 0812 345 6789\" required autocomplete=\"tel\" />\r\n                  </div>\r\n                </div>\r\n\r\n                <div class=\"checkout-input-group\">\r\n                  <div class=\"auth-label-row\">\r\n                    <label class=\"checkout-label\" for=\"auth-cust-address\">Home / Delivery Address</label>\r\n                    <button type=\"button\" class=\"auth-use-location-btn\" onclick=\"Chow45Auth.useCurrentLocationForCustomer()\">\r\n                      📍 Use my current location\r\n                    </button>\r\n                  </div>\r\n                  <div class=\"auth-input-wrap\">\r\n                    <span class=\"auth-input-icon\">📍</span>\r\n                    <input type=\"text\" id=\"auth-cust-address\" class=\"checkout-input auth-input\" placeholder=\"e.g. Block B, Hostel 4, OOU or 12 Adeola St.\" required autocomplete=\"street-address\" />\r\n                  </div>\r\n                  <small class=\"auth-field-hint\">You can type your address manually, or tap “Use my current location” to fill it automatically.</small>\r\n                </div>\r\n\r\n              <div class=\"checkout-input-group\">\r\n                <label class=\"checkout-label\" for=\"auth-cust-name\">Full Name <small style=\"color: var(--c-text-muted); font-weight: normal;\">(Optional)</small></label>\r\n                <div class=\"auth-input-wrap\">\r\n                  <span class=\"auth-input-icon\">👤</span>\r\n                  <input type=\"text\" id=\"auth-cust-name\" class=\"checkout-input auth-input\" placeholder=\"e.g. Boluwatife Adebayo\" autocomplete=\"name\" />\r\n                </div>\r\n              </div>\r\n\r\n              <div class=\"checkout-input-group\">\r\n                <label class=\"checkout-label\" for=\"auth-cust-password\">Create Password <small style=\"color: var(--c-text-muted); font-weight: normal;\">(Min 6 characters)</small></label>\r\n                <div class=\"auth-input-wrap\">\r\n                  <span class=\"auth-input-icon\">🔒</span>\r\n                  <input type=\"password\" id=\"auth-cust-password\" class=\"checkout-input auth-input\" placeholder=\"••••••••\" minlength=\"6\" autocomplete=\"new-password\" />\r\n                  <button type=\"button\" class=\"auth-pw-toggle\" onclick=\"Chow45Auth.togglePasswordVisibility('auth-cust-password', this)\">👁️</button>\r\n                </div>\r\n              </div>\r\n\r\n              <button type=\"submit\" id=\"auth-cust-btn\" class=\"cta-primary-btn auth-submit-btn\" style=\"margin-top: 16px;\">\r\n                <span>Start Ordering on Chow45 ✓</span>\r\n              </button>\r\n            </form>\r\n          </div>\r\n\r\n          <!-- ─── STEP 3: VENDOR SETUP (Store Name, Physical vs Online, Picture Upload) ─── -->\r\n          <div id=\"auth-step-vendor\" class=\"auth-flow-step\" style=\"display: none;\">\r\n            <div class=\"auth-panel-intro\">\r\n              <h3 class=\"auth-heading\">Join as a Food Vendor</h3>\r\n              <p class=\"auth-subheading\">Sell your food and reach students & campus customers.</p>\r\n            </div>\r\n\r\n            <!-- Email banner with Change button -->\r\n            <div style=\"display: flex; align-items: center; justify-content: space-between; background: #FAF6EB; padding: 10px 14px; border-radius: 12px; margin-top: 12px; margin-bottom: 12px; border: 1px solid rgba(12,81,63,0.15);\">\r\n              <div style=\"display: flex; align-items: center; gap: 8px; overflow: hidden;\">\r\n                <span style=\"font-size: 1rem;\">✉️</span>\r\n                <div style=\"overflow: hidden;\">\r\n                  <span style=\"font-size: 0.7rem; color: #6E6D66; display: block; text-transform: uppercase; font-weight: 700; letter-spacing: 0.05em;\">New vendor store for</span>\r\n                  <strong id=\"auth-vnd-email-display\" style=\"font-size: 0.88rem; color: #111111; display: block; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;\"></strong>\r\n                </div>\r\n              </div>\r\n              <button type=\"button\" onclick=\"Chow45Auth.showStep1()\" style=\"background: none; border: none; font-size: 0.78rem; font-weight: 700; color: #0C513F; cursor: pointer; text-decoration: underline; flex-shrink: 0; padding-left: 8px;\">Change</button>\r\n            </div>\r\n\r\n            <!-- Account Type Switcher: Customer vs Vendor -->\r\n            <div style=\"display: flex; gap: 8px; margin-bottom: 14px;\">\r\n              <button type=\"button\" onclick=\"Chow45Auth.showCustomerStep()\" style=\"flex: 1; padding: 8px 12px; border-radius: 8px; font-size: 0.8rem; font-weight: 700; background: #FAF6EB; color: #383834; border: 1px solid #E6DEC8; cursor: pointer;\">\r\n                🛍️ Order Food (Customer) ←\r\n              </button>\r\n              <button type=\"button\" style=\"flex: 1; padding: 8px 12px; border-radius: 8px; font-size: 0.8rem; font-weight: 800; background: #0C513F; color: #fff; border: 1px solid #0C513F; cursor: default;\">\r\n                🍳 Sell Food (Vendor) ✓\r\n              </button>\r\n            </div>\r\n\r\n            <div id=\"auth-vnd-alert\" class=\"auth-alert error\" style=\"display: none;\"></div>\r\n\r\n            <form onsubmit=\"event.preventDefault(); Chow45Auth.handleVendorSubmit();\">\r\n              <div class=\"checkout-input-group\">\r\n                <label class=\"checkout-label\" for=\"auth-vnd-store-name\">Store Name</label>\r\n                <div class=\"auth-input-wrap\">\r\n                  <span class=\"auth-input-icon\">🏪</span>\r\n                  <input type=\"text\" id=\"auth-vnd-store-name\" class=\"checkout-input auth-input\" placeholder=\"e.g. Sagamu Special Kitchen, Chef Dave Grills\" required />\r\n                </div>\r\n              </div>\r\n\r\n              <div class=\"checkout-input-group\">\r\n                <label class=\"checkout-label\">Store Type</label>\r\n                <div class=\"auth-store-type-grid\">\r\n                  <div class=\"auth-type-card selected\" id=\"type-card-physical\" onclick=\"Chow45Auth.setVendorStoreType('physical')\">\r\n                    <span class=\"type-icon\">🏪</span>\r\n                    <div>\r\n                      <strong>Physical Store</strong>\r\n                      <small>Canteen, restaurant, or walk-in shop</small>\r\n                    </div>\r\n                  </div>\r\n                  <div class=\"auth-type-card\" id=\"type-card-online\" onclick=\"Chow45Auth.setVendorStoreType('online')\">\r\n                    <span class=\"type-icon\">🍳</span>\r\n                    <div>\r\n                      <strong>Online Store</strong>\r\n                      <small>Home kitchen, cloud delivery & orders</small>\r\n                    </div>\r\n                  </div>\r\n                </div>\r\n              </div>\r\n\r\n              <!-- DYNAMIC PHOTO UPLOAD (Store Picture vs Food Picture) -->\r\n              <div class=\"checkout-input-group\">\r\n                <label class=\"checkout-label\" id=\"auth-vnd-upload-label\">Upload your store picture</label>\r\n                \r\n                <input type=\"file\" id=\"auth-vnd-photo-input\" accept=\"image/*\" style=\"display: none;\" onchange=\"Chow45Auth.handlePhotoUpload(event)\" />\r\n\r\n                <div class=\"auth-upload-dropzone\" onclick=\"Chow45Auth.triggerPhotoSelect()\">\r\n                  <div id=\"auth-dropzone-empty\">\r\n                    <div id=\"auth-dropzone-icon\" class=\"auth-dropzone-icon\">🏪</div>\r\n                    <div class=\"auth-dropzone-title\">Choose from Gallery or Take Photo</div>\r\n                    <div id=\"auth-vnd-upload-hint\" class=\"auth-dropzone-hint\">Upload storefront, restaurant entrance, or kitchen photo</div>\r\n                  </div>\r\n                  <div id=\"auth-dropzone-preview\" class=\"auth-photo-preview-wrap\" style=\"display: none;\">\r\n                    <img id=\"auth-vnd-photo-preview\" class=\"auth-photo-preview-img\" src=\"\" alt=\"Uploaded Preview\" />\r\n                    <div style=\"flex: 1; text-align: left;\">\r\n                      <strong style=\"display: block; font-size: 0.84rem; color: var(--c-primary);\">Photo uploaded ✓</strong>\r\n                      <small style=\"color: var(--c-text-muted); font-size: 0.74rem;\">Ready for your store profile</small>\r\n                    </div>\r\n                    <button type=\"button\" class=\"vnd-photo-change-btn\" onclick=\"event.stopPropagation(); Chow45Auth.triggerPhotoSelect();\">Change</button>\r\n                  </div>\r\n                </div>\r\n              </div>\r\n\r\n              <input type=\"hidden\" id=\"auth-vnd-email\" />\r\n\r\n              <div class=\"checkout-input-group\">\r\n                <label class=\"checkout-label\" for=\"auth-vnd-phone\">Store Phone Number</label>\r\n                <div class=\"auth-input-wrap\">\r\n                  <span class=\"auth-input-icon\">📱</span>\r\n                  <input type=\"tel\" id=\"auth-vnd-phone\" class=\"checkout-input auth-input\" placeholder=\"e.g. 0803 123 4567\" required autocomplete=\"tel\" />\r\n                </div>\r\n              </div>\r\n\r\n              <div class=\"checkout-input-group\">\r\n                <div class=\"auth-label-row\">\r\n                    <label class=\"checkout-label\" for=\"auth-vnd-address\">Store / Pickup Address</label>\r\n                    <button type=\"button\" class=\"auth-use-location-btn\" onclick=\"Chow45Auth.useCurrentLocationForVendor()\">\r\n                      📍 Use my current location\r\n                    </button>\r\n                  </div>\r\n                  <div class=\"auth-input-wrap\">\r\n                    <span class=\"auth-input-icon\">📍</span>\r\n                    <input type=\"text\" id=\"auth-vnd-address\" class=\"checkout-input auth-input\" placeholder=\"e.g. Science Canteen, Ago-Iwoye, Ogun\" required />\r\n                  </div>\r\n                  <small class=\"auth-field-hint\">Type your current address manually, or use your live location to populate it.</small>\r\n                </div>\r\n\r\n              <div class=\"checkout-input-group\">\r\n                <label class=\"checkout-label\" for=\"auth-vnd-password\">Store Password</label>\r\n                <div class=\"auth-input-wrap\">\r\n                  <span class=\"auth-input-icon\">🔒</span>\r\n                  <input type=\"password\" id=\"auth-vnd-password\" class=\"checkout-input auth-input\" placeholder=\"••••••••\" minlength=\"6\" autocomplete=\"new-password\" />\r\n                  <button type=\"button\" class=\"auth-pw-toggle\" onclick=\"Chow45Auth.togglePasswordVisibility('auth-vnd-password', this)\">👁️</button>\r\n                </div>\r\n              </div>\r\n\r\n              <button type=\"submit\" id=\"auth-vnd-btn\" class=\"cta-primary-btn auth-submit-btn\" style=\"margin-top: 16px;\">\r\n                <span>Register Store & Start Selling ✓</span>\r\n              </button>\r\n            </form>\r\n          </div>\r\n        </div>\r\n    </div>\r\n\r\n    <!-- Dedicated High-Priority Alert / Error Popup Modal -->\r\n    <div id=\"auth-error-popup\" class=\"auth-popup-backdrop\" style=\"display: none;\" onclick=\"Chow45Auth.onBackdropErrorPopupClick(event)\">\r\n      <div class=\"auth-popup-card\" role=\"alertdialog\" aria-modal=\"true\" aria-labelledby=\"auth-popup-title\" aria-describedby=\"auth-popup-message\">\r\n        <div class=\"auth-popup-icon-wrap\" id=\"auth-popup-icon\">⚠️</div>\r\n        <h3 class=\"auth-popup-title\" id=\"auth-popup-title\">Notice</h3>\r\n        <p class=\"auth-popup-message\" id=\"auth-popup-message\">Please upload your store picture to continue.</p>\r\n        <div class=\"auth-popup-actions\" id=\"auth-popup-actions\">\r\n          <button type=\"button\" class=\"auth-popup-btn primary\" onclick=\"Chow45Auth.closeErrorPopup()\">Okay, Got It</button>\r\n        </div>\r\n      </div>\r\n    </div>\r\n\r\n\r\n    <!-- Modal 10: User Account & Profile Sheet -->\r\n    <div id=\"account-modal\" class=\"modal-backdrop\">\r\n      <div class=\"modal-sheet\" style=\"max-width: 440px;\">\r\n        <div class=\"modal-header\">\r\n          <div class=\"modal-title\">My Account</div>\r\n          <button class=\"modal-close-btn\" onclick=\"document.getElementById('account-modal').classList.remove('open')\">✕</button>\r\n        </div>\r\n        <div class=\"modal-body\">\r\n          <div class=\"account-card-header\">\r\n            <div class=\"account-avatar\" id=\"account-avatar-char\">P</div>\r\n            <div class=\"account-details\">\r\n              <h3 id=\"account-display-name\" class=\"account-name\">Precious M.</h3>\r\n              <p id=\"account-display-email\" class=\"account-contact\">precious@chow45.com</p>\r\n              <p id=\"account-display-phone\" class=\"account-contact\">+234 812 450 4500</p>\r\n              <span id=\"account-role-badge\" class=\"account-badge customer\">Customer</span>\r\n            </div>\r\n          </div>\r\n\r\n          <div class=\"account-menu-list\">\r\n            <button class=\"account-menu-item\" onclick=\"Chow45App.openLocationModal(); document.getElementById('account-modal').classList.remove('open');\">\r\n              <span class=\"item-icon\">📍</span>\r\n              <div class=\"item-text\">\r\n                <strong>Saved Delivery Locations</strong>\r\n                <small id=\"account-locations-count\">Campus, Home, Work</small>\r\n              </div>\r\n              <span class=\"item-arrow\">→</span>\r\n            </button>\r\n\r\n            <button class=\"account-menu-item\" onclick=\"CustomerController.openOrderHistory(); document.getElementById('account-modal').classList.remove('open');\">\r\n              <span class=\"item-icon\">🛍️</span>\r\n              <div class=\"item-text\">\r\n                <strong>Order History</strong>\r\n                <small>View past orders & receipts</small>\r\n              </div>\r\n              <span class=\"item-arrow\">→</span>\r\n            </button>\r\n\r\n            <button class=\"account-menu-item\" onclick=\"CustomerController.openCart(); document.getElementById('account-modal').classList.remove('open');\">\r\n              <span class=\"item-icon\">🛒</span>\r\n              <div class=\"item-text\">\r\n                <strong>My Cart</strong>\r\n                <small>View active cart items</small>\r\n              </div>\r\n              <span class=\"item-arrow\">→</span>\r\n            </button>\r\n\r\n            <button id=\"account-vendor-dash-btn\" class=\"account-menu-item\" style=\"display: none; background: #E8F6F0;\" onclick=\"window.location.href='/vendor';\">\r\n              <span class=\"item-icon\">🏪</span>\r\n              <div class=\"item-text\">\r\n                <strong style=\"color: #0C513F;\">Vendor Dashboard</strong>\r\n                <small>Manage your food, menu & orders</small>\r\n              </div>\r\n              <span class=\"item-arrow\" style=\"color: #00B978;\">→</span>\r\n            </button>\r\n          </div>\r\n\r\n          <div class=\"account-logout-wrap\">\r\n            <button class=\"account-logout-btn\" onclick=\"Chow45Auth.signOut()\">\r\n              🚪 Sign Out of Chow45\r\n            </button>\r\n          </div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n\r\n    <!-- Modal: First-Time Vendor Setup (Password & Store Address) for tolaniakin2022@gmail.com -->\r\n    <div id=\"vendor-first-setup-modal\" class=\"modal-backdrop\">\r\n      <div class=\"modal-sheet vendor-first-setup-sheet\" style=\"max-width: 480px; border-radius: 20px; overflow: hidden; background: #fff;\">\r\n        <div class=\"modal-header\" style=\"border-bottom: 1px solid #f1f5f9; padding: 20px 24px 16px;\">\r\n          <div>\r\n            <div class=\"modal-title\" style=\"font-size: 1.25rem; font-weight: 800; color: #111; display: flex; align-items: center; gap: 8px;\">\r\n              <span>🔐</span> Set Your Password & Location\r\n            </div>\r\n            <p style=\"font-size: 0.86rem; color: #64748b; margin: 6px 0 0 0; line-height: 1.4;\">\r\n              Welcome, <strong>Tolani</strong>! An admin prepared your store and food menu. Please set your personal password and pickup address to complete your account activation.\r\n            </p>\r\n          </div>\r\n        </div>\r\n\r\n        <div class=\"modal-body\" style=\"padding: 20px 24px;\">\r\n          <form onsubmit=\"event.preventDefault(); Chow45Auth.submitFirstTimeSetup();\">\r\n            <!-- New Password -->\r\n            <div style=\"margin-bottom: 16px;\">\r\n              <label style=\"display: block; font-size: 0.8rem; font-weight: 700; color: #334155; margin-bottom: 6px; letter-spacing: 0.02em;\">\r\n                NEW PASSWORD <span style=\"color: #e11d48;\">*</span>\r\n              </label>\r\n              <div style=\"position: relative;\">\r\n                <input\r\n                  type=\"password\"\r\n                  id=\"vnd-setup-password\"\r\n                  required\r\n                  placeholder=\"At least 6 characters\"\r\n                  style=\"width: 100%; height: 46px; padding: 0 44px 0 14px; border: 1.5px solid #cbd5e1; border-radius: 12px; font-size: 0.95rem; box-sizing: border-box; outline: none;\"\r\n                />\r\n                <button\r\n                  type=\"button\"\r\n                  onclick=\"Chow45Auth.toggleSetupPasswordVisibility('vnd-setup-password', this)\"\r\n                  style=\"position: absolute; right: 12px; top: 50%; transform: translateY(-50%); background: none; border: none; cursor: pointer; font-size: 1.1rem; color: #64748b; padding: 4px;\"\r\n                >👁️</button>\r\n              </div>\r\n            </div>\r\n\r\n            <!-- Confirm New Password -->\r\n            <div style=\"margin-bottom: 18px;\">\r\n              <label style=\"display: block; font-size: 0.8rem; font-weight: 700; color: #334155; margin-bottom: 6px; letter-spacing: 0.02em;\">\r\n                CONFIRM NEW PASSWORD <span style=\"color: #e11d48;\">*</span>\r\n              </label>\r\n              <div style=\"position: relative;\">\r\n                <input\r\n                  type=\"password\"\r\n                  id=\"vnd-setup-password-confirm\"\r\n                  required\r\n                  placeholder=\"Re-type your new password\"\r\n                  style=\"width: 100%; height: 46px; padding: 0 44px 0 14px; border: 1.5px solid #cbd5e1; border-radius: 12px; font-size: 0.95rem; box-sizing: border-box; outline: none;\"\r\n                />\r\n                <button\r\n                  type=\"button\"\r\n                  onclick=\"Chow45Auth.toggleSetupPasswordVisibility('vnd-setup-password-confirm', this)\"\r\n                  style=\"position: absolute; right: 12px; top: 50%; transform: translateY(-50%); background: none; border: none; cursor: pointer; font-size: 1.1rem; color: #64748b; padding: 4px;\"\r\n                >👁️</button>\r\n              </div>\r\n            </div>\r\n\r\n            <!-- Store / Pickup Address -->\r\n            <div style=\"margin-bottom: 22px;\">\r\n              <label style=\"display: block; font-size: 0.8rem; font-weight: 700; color: #334155; margin-bottom: 6px; letter-spacing: 0.02em;\">\r\n                STORE / PICKUP LOCATION <span style=\"color: #e11d48;\">*</span>\r\n              </label>\r\n              <input\r\n                type=\"text\"\r\n                id=\"vnd-setup-address\"\r\n                required\r\n                value=\"sagamu\"\r\n                placeholder=\"e.g. Back of OOU Campus, Sagamu\"\r\n                style=\"width: 100%; height: 46px; padding: 0 14px; border: 1.5px solid #cbd5e1; border-radius: 12px; font-size: 0.95rem; box-sizing: border-box; outline: none; margin-bottom: 8px;\"\r\n              />\r\n              <div style=\"font-size: 0.78rem; color: #64748b; margin-bottom: 8px;\">\r\n                Where delivery riders will arrive to pick up customer food orders.\r\n              </div>\r\n\r\n              <!-- Quick Presets -->\r\n              <div style=\"display: flex; gap: 6px; flex-wrap: wrap;\">\r\n                <button\r\n                  type=\"button\"\r\n                  class=\"vnd-addr-chip\"\r\n                  onclick=\"document.getElementById('vnd-setup-address').value = 'Sagamu Campus (OSUTH), Sagamu, Ogun State'\"\r\n                  style=\"padding: 5px 10px; border-radius: 8px; border: 1px solid #cbd5e1; background: #f8fafc; font-size: 0.76rem; font-weight: 600; cursor: pointer; color: #1e293b;\"\r\n                >🏥 Sagamu Campus (OSUTH)</button>\r\n                <button\r\n                  type=\"button\"\r\n                  class=\"vnd-addr-chip\"\r\n                  onclick=\"document.getElementById('vnd-setup-address').value = 'OOU Main Campus Gate, Ago-Iwoye'\"\r\n                  style=\"padding: 5px 10px; border-radius: 8px; border: 1px solid #cbd5e1; background: #f8fafc; font-size: 0.76rem; font-weight: 600; cursor: pointer; color: #1e293b;\"\r\n                >🏫 OOU Main Campus</button>\r\n                <button\r\n                  type=\"button\"\r\n                  class=\"vnd-addr-chip\"\r\n                  onclick=\"document.getElementById('vnd-setup-address').value = 'Hospital Road, Sagamu, Ogun State'\"\r\n                  style=\"padding: 5px 10px; border-radius: 8px; border: 1px solid #cbd5e1; background: #f8fafc; font-size: 0.76rem; font-weight: 600; cursor: pointer; color: #1e293b;\"\r\n                >🏠 Hospital Road, Sagamu</button>\r\n              </div>\r\n            </div>\r\n\r\n            <!-- Error Banner -->\r\n            <div id=\"vnd-setup-error\" style=\"display: none; padding: 10px 14px; background: #fef2f2; border: 1px solid #fecaca; border-radius: 10px; color: #991b1b; font-size: 0.85rem; margin-bottom: 16px;\"></div>\r\n\r\n            <!-- Submit Button -->\r\n            <button\r\n              type=\"submit\"\r\n              id=\"vnd-setup-submit-btn\"\r\n              style=\"width: 100%; height: 50px; background: #000; color: #fff; border: none; border-radius: 14px; font-weight: 700; font-size: 0.98rem; cursor: pointer; display: flex; align-items: center; justify-content: center; gap: 8px; transition: background 0.2s;\"\r\n            >\r\n              <span>Save & Continue to Dashboard ➔</span>\r\n            </button>\r\n          </form>\r\n        </div>\r\n      </div>\r\n    </div>\r\n\r\n    <!-- Global Toast Container -->\r\n    <div id=\"toast-container\" class=\"toast-container\"></div>\r\n  </div>\r\n</div>";
